  var nativeSetAttr = Element.prototype.setAttribute;
  Element.prototype.setAttribute = function(n, v){
    var k = String(n).toLowerCase();
    if (k === "src" || k === "href" || k === "poster") v = fix(v);
    else if (k === "style") v = fixCss(v);
    return nativeSetAttr.call(this, n, v);
  };
  var nativeSetProp = CSSStyleDeclaration.prototype.setProperty;
  CSSStyleDeclaration.prototype.setProperty = function(n, v, pr){ return nativeSetProp.call(this, n, fixCss(v), pr); };
  // style.backgroundImage etc. live on CSSStyleProperties in newer Chrome, CSSStyleDeclaration elsewhere
  [window.CSSStyleProperties, window.CSS2Properties, window.CSSStyleDeclaration].forEach(function(C){
    if (!C) return;
    ["backgroundImage","background","cssText","maskImage","webkitMaskImage","listStyleImage","borderImage","content"].forEach(function(k){
      var d = Object.getOwnPropertyDescriptor(C.prototype, k); if (!d || !d.set) return;
      Object.defineProperty(C.prototype, k, { configurable:true, enumerable:d.enumerable, get:d.get, set:function(v){ d.set.call(this, fixCss(v)); } });
    });
  });
  CFG.fixTree = function(root){
    if (CFG.origin || !root.querySelectorAll) return root;
    root.querySelectorAll("[src],[href],[poster],[style]").forEach(function(el){
      ["src","href","poster"].forEach(function(a){ var v = el.getAttribute(a); if (rootRel(v)) nativeSetAttr.call(el, a, fix(v)); });
      var st = el.getAttribute("style"); if (st && st.indexOf("url(") >= 0) nativeSetAttr.call(el, "style", fixCss(st));
    });
    return root;
  };

  // fetch: serve bundled JSON from memory; send /api etc. to the server with cookies
  var nativeFetch = window.fetch.bind(window);
  window.fetch = function(input, init){
    var u = typeof input === "string" ? input : (input instanceof URL ? input.href : null);
    if (u != null) {
      var key = u.split(/[?#]/)[0];
      if (CFG.embed.hasOwnProperty(key)) {
        return Promise.resolve(new Response(CFG.embed[key], { status:200, headers:{ "Content-Type": /.html?$/.test(key) ? "text/html" : "application/json" } }));
      }
      if (!CFG.origin && rootRel(u)) return nativeFetch(fix(u), init);
      if (CFG.origin && rootRel(u)) {
        init = Object.assign({}, init);
        if (!init.credentials || init.credentials === "same-origin") init.credentials = "include";
        return nativeFetch(CFG.origin + u, init);
      }
    }
    return nativeFetch(input, init);
  };

  if (CFG.origin) {
    var ES = window.EventSource;
    if (ES) {
      var PES = function(u, o){ return new ES(toServer(u), o); };
      PES.prototype = ES.prototype; PES.CONNECTING = 0; PES.OPEN = 1; PES.CLOSED = 2;
