/**/
(() => {
  const STORE = "aether-cloak";
  const fav = (domain) => `https://www.google.com/s2/favicons?domain=${domain}&sz=64`;
  const PRESETS = [
    { id: "classroom", title: "Home", icon: fav("classroom.google.com"), name: "Google Classroom" },
    { id: "docs", title: "Google Docs", icon: fav("docs.google.com"), name: "Google Docs" },
    { id: "drive", title: "My Drive - Google Drive", icon: fav("drive.google.com"), name: "Google Drive" },
    { id: "google", title: "Google", icon: fav("google.com"), name: "Google" },
    { id: "canvas", title: "Dashboard", icon: fav("instructure.com"), name: "Canvas" },
    { id: "schoology", title: "Home | Schoology", icon: fav("schoology.com"), name: "Schoology" },
    { id: "clever", title: "Clever | Portal", icon: fav("clever.com"), name: "Clever" },
    { id: "khan", title: "Dashboard | Khan Academy", icon: fav("khanacademy.org"), name: "Khan Academy" },
    { id: "gmail", title: "Inbox - Gmail", icon: fav("mail.google.com"), name: "Gmail" },
    { id: "wikipedia", title: "Wikipedia", icon: fav("wikipedia.org"), name: "Wikipedia" },
  ];

  const original = { title: document.title, icons: null };

  const DEFAULT = { id: "schoology", title: "Home | Schoology", icon: fav("schoology.com"), onlyHidden: true };

  function read() {
    try {
      const raw = localStorage.getItem(STORE);
      if (raw === null) return { ...DEFAULT };
      const c = JSON.parse(raw);
      if (c && c.off) return null;
      if (c && typeof c.title === "string" && c.title.trim()) {
        return { id: String(c.id || "custom"), title: c.title.slice(0, 120), icon: typeof c.icon === "string" ? c.icon : "", onlyHidden: !!c.onlyHidden };
      }
    } catch {}
    return null;
  }

  function iconLinks() {
    return [...document.querySelectorAll('link[rel~="icon"], link[rel="apple-touch-icon"]')];
  }

  function rememberOriginal() {
    if (original.icons) return;
    original.icons = iconLinks().map((l) => ({ rel: l.rel, href: l.getAttribute("href"), sizes: l.getAttribute("sizes"), type: l.getAttribute("type") }));
  }

  function setIcon(href) {
    rememberOriginal();
    iconLinks().forEach((l) => l.remove());
    const link = document.createElement("link");
    link.rel = "icon";
    link.href = href;
    link.dataset.cloak = "1";
    document.head.appendChild(link);
  }

  function restore() {
    document.title = original.title;
    if (!original.icons) return;
    iconLinks().forEach((l) => l.remove());
    original.icons.forEach((o) => {
      const link = document.createElement("link");
      link.rel = o.rel;
      link.href = o.href;
      if (o.sizes) link.setAttribute("sizes", o.sizes);
      if (o.type) link.setAttribute("type", o.type);
      document.head.appendChild(link);
    });
    original.icons = null;
    if (window.aetherApplyIcons) window.aetherApplyIcons();
  }

  function wear(c) {
    document.title = c.title;
    if (c.icon) setIcon(c.icon);
    else restoreIconOnly();
  }

  function restoreIconOnly() {
    if (!original.icons) return;
    const t = document.title;
    restore();
    document.title = t;
  }

  function apply() {
    const c = read();
    if (!c) return restore();
    if (c.onlyHidden && document.visibilityState === "visible") return restore();
    wear(c);
  }

  function set(c) {
    if (!c) {
      try { localStorage.setItem(STORE, JSON.stringify({ off: true })); } catch {}
    } else {
      try { localStorage.setItem(STORE, JSON.stringify(c)); } catch {}
    }
    apply();
  }

  document.addEventListener("visibilitychange", apply);
  window.addEventListener("storage", (e) => {
    if (e.key === STORE) apply();
  });

  window.aetherCloak = { presets: PRESETS, defaults: DEFAULT, get: read, set, apply, clear: () => set(null) };
  apply();
})();

