body.script:
/**/
// Aether Onefile web proxy (Scramjet V1 + BareMux + Epoxy), running from static files.
// sw.js, scram/, baremux/ and epoxy/ must sit in the same folder as onefile.svg.
(function () {
  // ===== EDIT THIS: your Aether server's Wisp address, e.g. "wss://aether.example.com/" =====
  var AETHER_WISP = "";
  // ===========================================================================================

  // Folder that onefile.svg was loaded from (works on jsDelivr, staticdelivr, GitHub Pages…)
  var P = location.pathname.replace(/[^\/]*$/, "") || "/";

  function cleanWisp(url) {
    try {
      var u = new URL(String(url || "").trim());
      if (u.protocol !== "wss:" && u.protocol !== "ws:") return "";
      if (!/\/$/.test(u.pathname)) u.pathname += "/";
      return u.href;
    } catch (e) { return ""; }
  }
  function getWisp() {
    var saved = "";
    try { saved = localStorage.getItem("aether-wisp"); } catch (e) {}
    return cleanWisp(saved) || cleanWisp(AETHER_WISP);
  }
  function loadScript(src) {
    return new Promise(function (resolve, reject) {
      var s = document.createElement("script");
      s.src = src;
      s.async = false;
      s.onload = resolve;
      s.onerror = function () { reject(new Error("Couldn't load " + src)); };
      document.head.appendChild(s);
    });
  }

  async function init() {
    if (!("serviceWorker" in navigator)) throw new Error("This browser doesn't support service workers.");
    var wisp = getWisp();
    if (!wisp) throw new Error("No Wisp server is set. Put your Wisp address in AETHER_WISP inside onefile.svg.");

    await loadScript(P + "scram/scramjet.all.js");
    await loadScript(P + "baremux/index.js");

    var ScramjetController = window.$scramjetLoadController().ScramjetController;
    var sj = new ScramjetController({
      prefix: P + "scramjet/",
      files: {
        wasm: P + "scram/scramjet.wasm.wasm",
        all: P + "scram/scramjet.all.js",
        sync: P + "scram/scramjet.sync.js",
      },
    });
    await sj.init();

    var reg = await navigator.serviceWorker.register(P + "sw.js", { scope: P, updateViaCache: "none" });
    try { await reg.update(); } catch (e) {}
    await navigator.serviceWorker.ready;

    var conn = new window.BareMux.BareMuxConnection(P + "baremux/worker.js");
    await conn.setTransport(P + "epoxy/index.mjs", [{ wisp: wisp }]);

    window.scramjet = sj;
    window.aetherEncode = function (url) { return sj.encodeUrl(url); };
    window.aetherEngine = "scramjet-v1";
    window.aetherTransport = "epoxy";
    window.dispatchEvent(new Event("aether-ready"));
  }

  window.aetherReady = init().catch(function (err) {
    console.error("Aether Onefile: proxy failed to start", err);
    window.aetherError = err;
    window.dispatchEvent(new CustomEvent("aether-error", { detail: err.message }));
    throw err;
  });
  window.aetherReady.catch(function () {});
})();

