const SEASON_IMAGES = {
  winter: "/assets/images/aetherC-bg.jpg",
};

const SEASON_OVERLAYS = {
  winter: "0.68",
};

const SEASON_LABELS = {
  spring: "Spring",
  summer: "Summer",
  fall: "Fall",
  winter: "Winter / Christmas",
};

function getCurrentSeason(date = new Date()) {
  const month = date.getMonth();
  const day = date.getDate();
  if (month === 11 || month <= 1 || (month === 10 && day >= 26)) return "winter";
  if (month <= 4) return "spring";
  if (month <= 7) return "summer";
  return "fall";
}

const ICON_SETS = {
  normal: { 16: "/favicon-16.png", 32: "/favicon-32.png", ico: "/favicon.ico", apple: "/apple-touch-icon.png", tab: "/favicon-32.png" },
  christmas: {
    16: "/assets/images/seasonal/panda-16.png",
    32: "/assets/images/seasonal/panda-32.png",
    ico: "/assets/images/seasonal/panda-32.png",
    apple: "/assets/images/seasonal/panda-180.png",
    tab: "/assets/images/seasonal/panda-64.png",
  },
};

function currentIconSet() {
  return getCurrentThemeId() === "seasonal" && getCurrentSeason() === "winter" ? ICON_SETS.christmas : ICON_SETS.normal;
}

function applySiteIcons() {
  const set = currentIconSet();
  window.aetherTabIcon = set.tab;
  document.querySelectorAll("img.tab-fav").forEach((img) => {
    if (img.getAttribute("src") !== set.tab) img.src = set.tab;
  });
  if (document.querySelector("link[data-cloak]")) return;
  document.querySelectorAll('link[rel~="icon"], link[rel="apple-touch-icon"]').forEach((link) => {
    const sizes = link.getAttribute("sizes");
    const href = link.rel === "apple-touch-icon" ? set.apple : sizes === "16x16" ? set[16] : sizes === "32x32" ? set[32] : set.ico;
    if (link.getAttribute("href") !== href) {
      link.href = href;
      if (link.getAttribute("type") === "image/x-icon") link.type = "image/png";
    }
  });
}
window.aetherApplyIcons = applySiteIcons;

function themeImage(theme) {
  return theme.dynamic ? SEASON_IMAGES[getCurrentSeason()] || "" : theme.image || "";
}

function applyTheme(themeId) {
  const theme = THEMES.find((t) => t.id === themeId) || THEMES[0];
  const vars = theme.dynamic ? SEASON_PALETTES[getCurrentSeason()] : theme.vars;
  const merged = { "--c-text-secondary": "#ddd", ...vars };
  Object.entries(merged).forEach(([key, val]) => {
    document.documentElement.style.setProperty(key, val);
  });
  const image = themeImage(theme);
  document.documentElement.style.setProperty("--c-bg-image", image ? `url('${image}')` : "none");
  document.documentElement.style.setProperty("--c-bg-dim", image ? "0.5" : "0");
  document.documentElement.style.setProperty("--c-bg-overlay", (theme.dynamic && SEASON_OVERLAYS[getCurrentSeason()]) || "0.5");
  document.documentElement.classList.toggle("has-bg-image", Boolean(image));
  localStorage.setItem("aether-theme", theme.id);
  applySiteIcons();
}

function getButtonStyle() {
  try {
    return localStorage.getItem("aether-button-style") === "glass" ? "glass" : "normal";
  } catch {
    return "normal";
  }
}

function applyButtonStyle(style) {
  document.documentElement.classList.toggle("glass-ui", style === "glass");
  try {
    localStorage.setItem("aether-button-style", style === "glass" ? "glass" : "normal");
  } catch {}
}

applyButtonStyle(getButtonStyle());

const UI_PREFS = {
  corners: { key: "aether-corners", values: ["sharp", "rounded", "round"], fallback: "rounded" },
  compact: { key: "aether-compact", values: ["off", "on"], fallback: "off" },
  motion: { key: "aether-motion", values: ["auto", "on", "off"], fallback: "auto" },
  snow: { key: "aether-snow", values: ["on", "off"], fallback: "on" },
};

function getUiPref(name) {
  const p = UI_PREFS[name];
  let v = null;
  try {
    v = localStorage.getItem(p.key);
  } catch {}
  return p.values.includes(v) ? v : p.fallback;
}

const motionQuery = window.matchMedia ? window.matchMedia("(prefers-reduced-motion: reduce)") : null;

function reduceMotionOn() {
  const m = getUiPref("motion");
  return m === "on" || (m === "auto" && Boolean(motionQuery && motionQuery.matches));
}

function syncChromeTop() {
  const content = document.getElementById("tabcontent");
  if (content) document.documentElement.style.setProperty("--chrome-top", `${Math.round(content.getBoundingClientRect().top)}px`);
}

function applyUiPrefs() {
  const root = document.documentElement;
  const corners = getUiPref("corners");
  root.classList.toggle("corners-sharp", corners === "sharp");
  root.classList.toggle("corners-round", corners === "round");
  root.classList.toggle("compact", getUiPref("compact") === "on");
  root.classList.toggle("reduce-motion", reduceMotionOn());
  syncChromeTop();
  window.dispatchEvent(new Event("aether-uiprefs"));
}

function setUiPref(name, value) {
  try {
    localStorage.setItem(UI_PREFS[name].key, value);
  } catch {}
  applyUiPrefs();
}

applyUiPrefs();
if (motionQuery && motionQuery.addEventListener) motionQuery.addEventListener("change", applyUiPrefs);
window.addEventListener("resize", syncChromeTop);
window.addEventListener("load", syncChromeTop);
if (window.ResizeObserver && document.getElementById("tabcontent")) new ResizeObserver(syncChromeTop).observe(document.getElementById("tabcontent"));
window.addEventListener("storage", (e) => {
  if (e.key && Object.values(UI_PREFS).some((p) => p.key === e.key)) applyUiPrefs();
});
window.addEventListener("storage", (e) => {
  if (e.key === "aether-button-style") applyButtonStyle(getButtonStyle());
});

function getCurrentThemeId() {
  return localStorage.getItem("aether-theme") || "aether";
}

applyTheme(getCurrentThemeId());

let lastSeason = getCurrentSeason();
setInterval(() => {
  const now = getCurrentSeason();
  if (now !== lastSeason) {
    lastSeason = now;
    if (getCurrentThemeId() === "seasonal") applyTheme("seasonal");
  }
}, 60 * 1000);
/**/

/**/
function toPublicUrl(diskPath) {
  if (diskPath.startsWith("/")) return diskPath;
  return "/" + diskPath.replace(/^public\//, "");
}

function getFavorites(type) {
  return JSON.parse(localStorage.getItem(`aether-favorites-${type}`) || "[]");
}

function isFavorited(type, url) {
  return getFavorites(type).includes(url);
}

function toggleFavorite(type, url) {
  let favs = getFavorites(type);
  if (favs.includes(url)) {
    favs = favs.filter((u) => u !== url);
  } else {
    favs.push(url);
  }
  localStorage.setItem(`aether-favorites-${type}`, JSON.stringify(favs));
}

function attachToolbar(wrap, items, renderFn, type) {
  let query = "";
  let sort = "az";

  function apply() {
    let filtered = items.filter((i) => i.name.toLowerCase().includes(query.toLowerCase()));

    if (sort === "favorites") {
      filtered = filtered.filter((i) => isFavorited(type, i.url));
      filtered.sort((a, b) => a.name.localeCompare(b.name));
    } else if (sort === "az") {
      filtered.sort((a, b) => a.name.localeCompare(b.name));
    } else if (sort === "za") {
      filtered.sort((a, b) => b.name.localeCompare(a.name));
    }

    renderFn(filtered);
  }

  const searchInput = wrap.querySelector(".content-search input");
  const sortSelect = wrap.querySelector(".content-sort-select");

  searchInput.addEventListener("input", () => {
    query = searchInput.value;
    apply();
  });

  sortSelect.addEventListener("change", () => {
    sort = sortSelect.value;
    apply();
  });

  return apply;
}

function buildCard(item, type, onLaunch, refresh) {
  const card = document.createElement("div");
  card.className = "activity-card";
  const imgUrl = toPublicUrl(item.image);
  const favored = isFavorited(type, item.url);

  card.innerHTML = `
    <img src="${imgUrl}" alt="${item.name}" />
    <div class="activity-label">${item.name}</div>
    <span class="activity-fav-star ${favored ? "active" : ""}" title="Favorite">
      <i class="fa-${favored ? "solid" : "regular"} fa-star"></i>
    </span>
  `;

  card.onclick = onLaunch;

  card.querySelector(".activity-fav-star").onclick = (e) => {
    e.stopPropagation();
    toggleFavorite(type, item.url);
    refresh();
  };

  return card;
}

async function buildAppsPage(tabId) {
  const wrap = document.createElement("div");
  wrap.className = "content-page";
  wrap.innerHTML = `
    <div class="content-title">Apps</div>
    <div class="content-subtitle">Loading...</div>
    <div class="content-toolbar wide">
      <div class="content-search"><i class="fa-solid fa-magnifying-glass"></i><input type="text" placeholder="Search apps..." /></div>
      <select class="content-sort-select">
        <option value="az">A-Z</option>
        <option value="za">Z-A</option>
        <option value="favorites">Favorites</option>
      </select>
    </div>
    <div class="apps-grid"></div>
  `;

  try {
    const res = await fetch("/data/apps.json");
    const list = await res.json();
    wrap.querySelector(".content-subtitle").textContent = `${list.length} apps`;

    const grid = wrap.querySelector(".apps-grid");
    let apply;

    function render(items) {
      grid.innerHTML = "";
      if (!items.length) {
        grid.innerHTML = `<div class="content-empty">No apps match your search.</div>`;
        return;
      }
      items.forEach((a) => {
        grid.appendChild(
          buildCard(
            a,
            "apps",
            () => createTab(a.url, { showLaunchLoading: true, appName: a.name }),
            () => apply()
          )
        );
      });
    }

    apply = attachToolbar(wrap, list, render, "apps");
    apply();
  } catch (err) {
    wrap.querySelector(".content-subtitle").textContent = "Failed to load apps.";
    console.error("Aether: failed to load apps.json", err);
  }

  return wrap;
}

let randomCardTimer = null;

function stopRandomCard() {
  if (randomCardTimer) clearInterval(randomCardTimer);
  randomCardTimer = null;
}

function buildRandomCard(list) {
  const card = document.createElement("div");
  card.className = "activity-card random-card";
  card.title = "Play a random activity";
  card.innerHTML = `
    <img alt="" />
    <div class="random-card-shade"></div>
    <div class="random-card-icon"><i class="fa-solid fa-shuffle"></i></div>
    <div class="activity-label"><span class="random-card-tag">Random</span> <span class="random-card-name"></span></div>
  `;
  const img = card.querySelector("img");
  const name = card.querySelector(".random-card-name");
  let index = Math.floor(Math.random() * list.length);
  let rolling = false;

  function show(i) {
    const a = list[i];
    img.src = toPublicUrl(a.image);
    name.textContent = a.name;
  }

  function next() {
    let i = Math.floor(Math.random() * list.length);
    if (i === index) i = (i + 1) % list.length;
    index = i;
    show(index);
  }

  show(index);
  randomCardTimer = setInterval(() => {
    if (!card.isConnected) return stopRandomCard();
    if (!rolling) next();
  }, 1800);

  card.onclick = () => {
    if (rolling) return;
    rolling = true;
    card.classList.add("rolling");
    let step = 0;
    const steps = 14;
    const spin = () => {
      next();
      step++;
      if (step < steps) return setTimeout(spin, 40 + step * step * 2);
      const pick = list[index];
      setTimeout(() => {
        rolling = false;
        card.classList.remove("rolling");
        createTab(pick.url, { showLaunchLoading: true, appName: pick.name });
      }, 350);
    };
    spin();
  };

  return card;
}

async function buildActivitiesPage(tabId) {
  const wrap = document.createElement("div");
  wrap.className = "content-page";
  wrap.innerHTML = `
    <div class="content-title">Activities</div>
    <div class="content-subtitle">Loading...</div>
    <div class="content-toolbar wide">
      <div class="content-search"><i class="fa-solid fa-magnifying-glass"></i><input type="text" placeholder="Search activities..." /></div>
      <select class="content-sort-select">
        <option value="az">A-Z</option>
        <option value="za">Z-A</option>
        <option value="favorites">Favorites</option>
      </select>
    </div>
    <div class="activities-grid"></div>
  `;

  try {
    const res = await fetch("/data/activities.json");
    const raw = await res.json();
    const list = raw.map((a) => ({
      ...a,
      url: /^https?:\/\//i.test(a.url) ? a.url : toPublicUrl(a.url),
    }));
    wrap.querySelector(".content-subtitle").textContent = `${list.length} activities`;

    const grid = wrap.querySelector(".activities-grid");
    let apply;

    const searchBox = wrap.querySelector(".content-search input");
    const sortBox = wrap.querySelector(".content-sort-select");

    function render(items) {
      stopRandomCard();
      grid.innerHTML = "";
      if (!items.length) {
        grid.innerHTML = `<div class="content-empty">No activities match your search.</div>`;
        return;
      }
      if (!searchBox.value.trim() && sortBox.value !== "favorites" && list.length > 1) grid.appendChild(buildRandomCard(list));
      items.forEach((a) => {
        grid.appendChild(
          buildCard(
            a,
            "activities",
            () => createTab(a.url, { showLaunchLoading: true, appName: a.name }),
            () => apply()
          )
        );
      });
    }

    apply = attachToolbar(wrap, list, render, "activities");
    apply();
  } catch (err) {
    wrap.querySelector(".content-subtitle").textContent = "Failed to load activities.";
    console.error("Aether: failed to load activities.json", err);
  }

  return wrap;
}
