    function updatePreview() {
      const t = THEMES.find((th) => th.id === select.value);
      const vars = t.dynamic ? SEASON_PALETTES[getCurrentSeason()] : t.vars;

      const image = themeImage(t);
      if (image) {
        swatchStrip.style.display = "none";
        imagePreview.style.display = "block";
        imagePreview.style.backgroundImage = `linear-gradient(rgba(0,0,0,0.2), rgba(0,0,0,0.2)), url('${window.__AETHER_SVG__ ? window.__AETHER_SVG__.fix(image) : image}')`;
      } else {
        imagePreview.style.display = "none";
        swatchStrip.style.display = "flex";
        swatchStrip.innerHTML = `
          <div class="theme-swatch" style="background:${vars["--c-bg"]}"></div>
          <div class="theme-swatch" style="background:${vars["--c-surface-2"]}"></div>
          <div class="theme-swatch" style="background:${vars["--c-accent"]}"></div>
        `;
      }
    }

    select.value = getCurrentThemeId();
    updatePreview();

    select.addEventListener("change", () => {
      applyTheme(select.value);
      updatePreview();
    });
  }

