  function renderCloak() {
    const cloak = window.aetherCloak;
    const cloakGrid = body.querySelector(".cloak-grid");
    if (!cloak || !cloakGrid) return;
    const titleInput = body.querySelector(".cloak-title");
    const iconInput = body.querySelector(".cloak-icon");
    const hiddenBox = body.querySelector(".cloak-hidden");

    function iconFrom(value) {
      const v = value.trim();
      if (!v) return "";
      if (/^(https?:|data:image\/)/i.test(v) && /\.(png|ico|svg|jpe?g|gif|webp)(\?|#|$)|^data:/i.test(v)) return v;
      try {
        const host = new URL(/^https?:\/\//i.test(v) ? v : `https://${v}`).hostname;
        return `https://www.google.com/s2/favicons?domain=${encodeURIComponent(host)}&sz=64`;
      } catch {
        return "";
      }
    }

    function paint() {
      const current = cloak.get();
      cloakGrid.querySelectorAll(".cloak-option").forEach((b) => b.classList.toggle("active", !!current && current.id === b.dataset.id));
      hiddenBox.checked = !!(current && current.onlyHidden);
      if (current && current.id === "custom") {
        titleInput.value = current.title;
      }
    }

    cloak.presets.forEach((p) => {
      const b = document.createElement("button");
      b.className = "cloak-option";
      b.dataset.id = p.id;
      const img = document.createElement("img");
      img.src = p.icon;
      img.alt = "";
      const label = document.createElement("span");
      label.textContent = p.name;
      b.append(img, label);
      b.onclick = () => {
        cloak.set({ id: p.id, title: p.title, icon: p.icon, onlyHidden: hiddenBox.checked });
        paint();
      };
      cloakGrid.appendChild(b);
    });

    body.querySelector(".cloak-save").onclick = () => {
      const title = titleInput.value.trim();
      if (!title) return titleInput.focus();
      cloak.set({ id: "custom", title, icon: iconFrom(iconInput.value), onlyHidden: hiddenBox.checked });
      paint();
    };
    body.querySelector(".cloak-reset").onclick = () => {
      cloak.clear();
      titleInput.value = "";
      iconInput.value = "";
      paint();
    };
    hiddenBox.onchange = () => {
      const current = cloak.get();
      if (current) cloak.set({ ...current, onlyHidden: hiddenBox.checked });
    };
    paint();
  }

  async function renderServiceWorker() {
    body.innerHTML = `
      <div class="settings-content-title">Search Engine</div>
      <div class="settings-content-subtitle">Choose which engine handles browsing</div>
      <hr class="settings-divider" />
      <select class="engine-select">
        <option value="scramjet">Scramjet V2 (Default)</option>
        <option value="scramjet-v1">Scramjet V1</option>
        <option value="ultraviolet">Ultraviolet</option>
      </select>
      <div class="sw-hint">Switching engines reloads the page.</div>
      <div class="settings-content-title" style="font-size: 18px; margin-top: 24px;">Transport</div>
      <div class="settings-content-subtitle">How the engine connects to websites. If sites load slowly or break, try the other one.</div>
      <select class="engine-select transport-select">
        <option value="libcurl">libcurl</option>
        <option value="epoxy">Epoxy</option>
      </select>
      <div class="sw-hint">Switching transports reloads the page.</div>
      <div class="settings-content-title" style="font-size: 18px; margin-top: 24px;">Wisp Server</div>
      <div class="settings-content-subtitle">The server the transport connects through. Leave it on this site's server unless you have another one.</div>
      <div class="wisp-row">
        <input class="wisp-input" type="text" spellcheck="false" autocomplete="off" placeholder="wss://example.com/wisp/" />
        <button class="wisp-btn wisp-test" type="button">Test</button>
        <button class="wisp-btn wisp-save" type="button">Save</button>
      </div>
      <div class="wisp-status sw-hint"></div>
      <button class="wisp-reset" type="button">Use this site's server</button>
      <hr class="settings-divider" style="margin-top: 28px;" />
      <div class="settings-content-title" style="font-size: 18px;">Service Worker</div>
      <div class="settings-content-subtitle">Reset the engine if pages stop loading correctly</div>
      <div class="sw-status">Checking status...</div>
      <button class="sw-unregister-btn"><i class="fa-solid fa-trash"></i> Unregister Service Worker</button>
      <div class="sw-hint">Sites won't load until you reload the page after doing this.</div>
    `;

    const engineSelect = body.querySelector(".engine-select");
    engineSelect.value = localStorage.getItem("aether-engine") || "scramjet";
    engineSelect.addEventListener("change", () => {
      window.setEngine(engineSelect.value);
    });

    const transportSelect = body.querySelector(".transport-select");
    const engineNow = localStorage.getItem("aether-engine") || "scramjet";
    const defaultT = engineNow === "scramjet" ? "libcurl" : "epoxy";
    const savedT = localStorage.getItem("aether-transport");
    transportSelect.value = savedT === "libcurl" || savedT === "epoxy" ? savedT : defaultT;
    transportSelect.querySelectorAll("option").forEach((o) => {
      if (o.value === defaultT) o.textContent += " (Default)";
    });
    transportSelect.addEventListener("change", () => {
      if (typeof window.setAetherTransport === "function") window.setAetherTransport(transportSelect.value);
      else {
        localStorage.setItem("aether-transport", transportSelect.value);
        location.reload();
      }
    });

    const wispInput = body.querySelector(".wisp-input");
    const wispStatus = body.querySelector(".wisp-status");
    const wispReset = body.querySelector(".wisp-reset");
    const siteWisp = `${location.protocol === "https:" ? "wss:" : "ws:"}//${location.host}/`;
    const clean = (v) => (typeof window.cleanAetherWisp === "function" ? window.cleanAetherWisp(v) : /^wss?:\/\//i.test(String(v).trim()) ? String(v).trim() : "");
    const savedWisp = clean(localStorage.getItem("aether-wisp") || "");
    wispInput.value = savedWisp || siteWisp;
    wispReset.hidden = !savedWisp;
    wispStatus.textContent = savedWisp ? "Using a custom Wisp server." : "Using this site's Wisp server.";
    const setWispStatus = (text, kind) => {
      wispStatus.textContent = text;
      wispStatus.className = `wisp-status sw-hint${kind ? " " + kind : ""}`;
    };
    const testWisp = (url) =>
      new Promise((resolve) => {
        let done = false;
        let ws;
        const finish = (ok, why) => {
          if (done) return;
          done = true;
          try {
            ws.close();
          } catch {
          }
          resolve({ ok, why });
        };
        try {
          ws = new WebSocket(url);
        } catch {
          return resolve({ ok: false, why: "That address isn't valid." });
        }
        ws.binaryType = "arraybuffer";
        ws.onopen = () => finish(true);
        ws.onerror = () => finish(false, "Couldn't connect to that server.");
        ws.onclose = () => finish(false, "The server closed the connection.");
        setTimeout(() => finish(false, "The server didn't answer in time."), 6000);
      });
    body.querySelector(".wisp-test").onclick = async () => {
      const url = clean(wispInput.value);
      if (!url) return setWispStatus("Wisp servers start with wss:// or ws://", "bad");
      setWispStatus("Testing...");
      const r = await testWisp(url);
      setWispStatus(r.ok ? "Connected. This server works." : r.why, r.ok ? "good" : "bad");
    };
    body.querySelector(".wisp-save").onclick = async () => {
      const url = clean(wispInput.value);
      if (!url) return setWispStatus("Wisp servers start with wss:// or ws://", "bad");
      if (url === siteWisp) {
        localStorage.removeItem("aether-wisp");
        return location.reload();
      }
      setWispStatus("Testing before saving...");
      const r = await testWisp(url);
      if (!r.ok) return setWispStatus(`${r.why} Not saved.`, "bad");
      if (typeof window.setAetherWisp === "function") window.setAetherWisp(url);
      else {
        localStorage.setItem("aether-wisp", url);
        location.reload();
      }
    };
    wispReset.onclick = () => {
      localStorage.removeItem("aether-wisp");
      location.reload();
    };

    const statusEl = body.querySelector(".sw-status");
    const btn = body.querySelector(".sw-unregister-btn");

    async function refreshStatus() {
      if (!("serviceWorker" in navigator)) {
        statusEl.textContent = "Service workers aren't supported in this browser.";
        btn.disabled = true;
        return;
      }
      const regs = await navigator.serviceWorker.getRegistrations();
      statusEl.textContent = regs.length
        ? `${regs.length} service worker${regs.length > 1 ? "s" : ""} currently registered.`
        : "No service worker is currently registered.";
      btn.disabled = regs.length === 0;
    }

    btn.onclick = async () => {
      btn.disabled = true;
      btn.innerHTML = `<i class="fa-solid fa-spinner fa-spin"></i> Unregistering...`;
      const regs = await navigator.serviceWorker.getRegistrations();
      await Promise.all(regs.map((r) => r.unregister()));
      btn.innerHTML = `<i class="fa-solid fa-trash"></i> Unregister Service Worker`;
      await refreshStatus();
      alert("Service worker unregistered. Reload the page for sw to work");
    };

    await refreshStatus();
  }

  function renderHistory() {
    body.innerHTML = `
      <div class="settings-content-title">History</div>
      <div class="settings-content-subtitle">Pages you've visited</div>
      <hr class="settings-divider" />
      <div class="content-toolbar wide" style="margin-bottom: 20px;">
        <div class="content-search"><i class="fa-solid fa-magnifying-glass"></i><input type="text" placeholder="Search history..." /></div>
        <button class="history-clear-btn"><i class="fa-solid fa-trash"></i> Clear</button>
      </div>
      <div class="history-list"></div>
    `;

    const list = body.querySelector(".history-list");
    const searchInput = body.querySelector(".content-search input");

    function render() {
      const history = getHistory();
      const query = searchInput.value.toLowerCase();
      const filtered = history.filter((h) => h.url.toLowerCase().includes(query));

      list.innerHTML = "";
      if (!filtered.length) {
        list.innerHTML = `<div class="content-empty">No history yet.</div>`;
        return;
      }

      filtered.forEach((h) => {
        const row = document.createElement("div");
        row.className = "history-entry";
        const date = new Date(h.time);
        row.innerHTML = `
          <div class="history-entry-url">${h.url}</div>
          <div class="history-entry-time">${date.toLocaleString()}</div>
        `;
        row.onclick = () => createTab(h.url);
        list.appendChild(row);
      });
    }

    searchInput.addEventListener("input", render);
    body.querySelector(".history-clear-btn").onclick = () => {
      if (confirm("Clear all browsing history?")) {
        clearHistory();
        render();
      }
    };

    render();
  }

  function renderCredits() {
    body.innerHTML = `
      <div class="settings-content-title">Credits</div>
      <div class="settings-content-subtitle">People and projects to the succession behind Aether</div>
      <hr class="settings-divider" />
    `;
    renderCreditsList(body);
  }

  function setActive(panel) {
    navItems.forEach((el) => el.classList.toggle("active", el.dataset.panel === panel));
    if (panel === "appearance") renderAppearance();
    else if (panel === "account") renderAccountPanel(body);
    else if (panel === "misc") renderMisc();
    else if (panel === "history") renderHistory();
    else renderCredits();
  }

  navItems.forEach((el) => {
    el.onclick = () => setActive(el.dataset.panel);
  });

  setActive("appearance");

  return wrap;
}
