function showLaunchLoading(frameWrap, iframe, appName) {
  const overlay = document.createElement("div");
  overlay.className = "launch-loading";
  overlay.innerHTML = `
    <div class="launch-loading-spinner"></div>
    <div class="launch-loading-text">Launching ${appName || "application"}...</div>
    <div class="launch-loading-subtext"></div>
  `;
  frameWrap.appendChild(overlay);

  const subtext = overlay.querySelector(".launch-loading-subtext");

  const slowTimer = setTimeout(() => {
    subtext.innerHTML = `This is taking longer than usual. Try <kbd>Ctrl</kbd> + <kbd>Shift</kbd> + <kbd>R</kbd>.`;
  }, 8000);

  function cleanup() {
    clearTimeout(slowTimer);
    overlay.remove();
    iframe.removeEventListener("load", cleanup);
  }

  iframe.addEventListener("load", cleanup);
}

