/**/
const AI_CHATS_KEY = "aether-ai-chats";
const AI_OLD_KEY = "aether-ai-chat";
const AI_KEY_STORE = "ai-personal-key";
const AI_MAX_CHATS = 30;
const AI_MAX_MESSAGES = 40;
const AI_MAX_SAVE_CHARS = 900000;
const AI_STARTERS = [
  "Explain photosynthesis like I'm 12",
  "Help me study for a history test",
  "How do I solve 2x + 5 = 17?",
  "Give me ideas for a science project",
  "Who is anzo?",
];
const AI_PROVIDERS = [
  { id: "groq", name: "Groq", hint: "Starts with gsk_", url: "https://console.groq.com/keys" },
  { id: "gemini", name: "Google Gemini", hint: "Starts with AIza", url: "https://aistudio.google.com/apikey" },
  { id: "openrouter", name: "OpenRouter", hint: "Starts with sk-or-", url: "https://openrouter.ai/keys" },
  { id: "openai", name: "OpenAI", hint: "Starts with sk-", url: "https://platform.openai.com/api-keys" },
  { id: "anthropic", name: "Anthropic (Claude)", hint: "Starts with sk-ant-", url: "https://console.anthropic.com/settings/keys" },
];

const ai = {
  pending: [],
  chats: [],
  currentId: null,
  busy: false,
  controller: null,
  siteReady: null,
  sideOpen: false,
  ui: null,
};

function aiEl(tag, cls, text) {
  const e = document.createElement(tag);
  if (cls) e.className = cls;
  if (text !== undefined) e.textContent = text;
  return e;
}
function aiIcon(name) {
  const i = document.createElement("i");
  i.className = `fa-solid fa-${name}`;
  return i;
}

const AI_MAX_IMAGES = Infinity;

function aiValidThumbs(list) {
  return Array.isArray(list) ? list.filter((u) => typeof u === "string" && /^data:image\//.test(u)).slice(0, AI_MAX_IMAGES) : [];
}

function aiValidMessages(list) {
  return Array.isArray(list)
    ? list
        .filter((m) => m && (m.role === "user" || m.role === "assistant") && typeof m.content === "string")
        .map((m) => {
          const thumbs = aiValidThumbs(m.thumbs);
          return thumbs.length ? { role: m.role, content: m.content, thumbs } : { role: m.role, content: m.content };
        })
    : [];
}

function aiForSaving(m) {
  return m.thumbs && m.thumbs.length ? { role: m.role, content: m.content, thumbs: m.thumbs } : { role: m.role, content: m.content };
}

function aiNewId() {
  return `c${Date.now().toString(36)}${Math.random().toString(36).slice(2, 6)}`;
}

function aiLoadChats() {
  let data = null;
  try {
    data = JSON.parse(localStorage.getItem(AI_CHATS_KEY) || "null");
  } catch {
    data = null;
  }
  let chats = data && Array.isArray(data.chats) ? data.chats : [];
  chats = chats
    .filter((c) => c && typeof c.id === "string")
    .map((c) => ({
      id: c.id,
      title: typeof c.title === "string" ? c.title.slice(0, 80) : "",
      updated: Number(c.updated) || 0,
      messages: aiValidMessages(c.messages),
    }))
    .filter((c) => c.messages.length);

  let migrated = false;
  try {
    const old = aiValidMessages(JSON.parse(localStorage.getItem(AI_OLD_KEY) || "[]"));
    if (old.length) {
      chats.unshift({ id: aiNewId(), title: "", updated: Date.now(), messages: old });
      migrated = true;
    }
    if (localStorage.getItem(AI_OLD_KEY) !== null) localStorage.removeItem(AI_OLD_KEY);
  } catch {
  }

  chats.sort((a, b) => b.updated - a.updated);
  ai.chats = chats;
  ai.currentId = data && chats.some((c) => c.id === data.current) ? data.current : null;
  if (migrated) aiSaveChats();
}

function aiSaveChats() {
  const chats = ai.chats
    .filter((c) => c.messages.length)
    .sort((a, b) => b.updated - a.updated)
    .slice(0, AI_MAX_CHATS)
    .map((c) => ({
      id: c.id,
      title: c.title || aiTitleFrom(c.messages),
      updated: c.updated,
      messages: c.messages.slice(-AI_MAX_MESSAGES).map(aiForSaving),
    }));
  let text = JSON.stringify({ current: ai.currentId, chats });
  while (text.length > AI_MAX_SAVE_CHARS && chats.length > 1) {
    chats.pop();
    text = JSON.stringify({ current: ai.currentId, chats });
  }
  try {
    localStorage.setItem(AI_CHATS_KEY, text);
  } catch {
  }
}

function aiTitleFrom(messages) {
  const first = messages.find((m) => m.role === "user");
  const t = first ? first.content.replace(/\s+/g, " ").trim() : "";
  if (!t && first && first.thumbs && first.thumbs.length) return "Image";
  return t ? (t.length > 48 ? `${t.slice(0, 47)}…` : t) : "New chat";
}

function aiCurrent() {
  return ai.chats.find((c) => c.id === ai.currentId) || null;
}

function aiPersonalKey() {
  try {
    const k = JSON.parse(localStorage.getItem(AI_KEY_STORE) || "null");
    if (k && typeof k.key === "string" && k.key && AI_PROVIDERS.some((p) => p.id === k.provider)) {
      return { key: k.key, provider: k.provider, model: typeof k.model === "string" ? k.model : "" };
    }
  } catch {
  }
  return null;
}
function aiSetPersonalKey(value) {
  try {
    if (value) localStorage.setItem(AI_KEY_STORE, JSON.stringify(value));
    else localStorage.removeItem(AI_KEY_STORE);
  } catch {
  }
}
function aiKeyHeaders(k) {
  if (!k) return {};
  const h = { "X-AI-Key": k.key, "X-AI-Provider": k.provider };
  if (k.model) h["X-AI-Model"] = k.model;
  return h;
}

window.addEventListener("storage", (e) => {
  if (e.key === AI_CHATS_KEY && !ai.busy) {
    aiLoadChats();
    aiRenderAll();
  }
});

aiLoadChats();

function aiInline(text, parent) {
  const re = /(`[^`\n]+`|\*\*[^*\n]+\*\*|\*[^*\n]+\*|https?:\/\/[^\s<>()]+[^\s<>().,!?;:'"])/g;
  let last = 0;
  let m;
  while ((m = re.exec(text))) {
    if (m.index > last) parent.appendChild(document.createTextNode(text.slice(last, m.index)));
    const tok = m[0];
    if (tok.startsWith("`")) parent.appendChild(aiEl("code", "ai-code-inline", tok.slice(1, -1)));
    else if (tok.startsWith("**")) parent.appendChild(aiEl("strong", "", tok.slice(2, -2)));
    else if (tok.startsWith("*")) parent.appendChild(aiEl("em", "", tok.slice(1, -1)));
    else {
      const a = aiEl("a", "", tok);
      a.href = tok;
      a.target = "_blank";
      a.rel = "noopener noreferrer";
      parent.appendChild(a);
    }
    last = m.index + tok.length;
  }
  if (last < text.length) parent.appendChild(document.createTextNode(text.slice(last)));
}

const AI_HLJS_URL = "https://cdnjs.cloudflare.com/ajax/libs/highlight.js/11.9.0/highlight.min.js";
const aiHljs = { state: "idle", queue: [] };

function aiLoadHljs() {
  if (aiHljs.state !== "idle") return;
  aiHljs.state = "loading";
  const tag = document.createElement("script");
  tag.src = AI_HLJS_URL;
  tag.async = true;
  tag.onload = () => {
    aiHljs.state = window.hljs ? "ready" : "failed";
    const queue = aiHljs.queue.splice(0);
    if (aiHljs.state === "ready") queue.forEach((job) => aiHighlightNow(job.el, job.code, job.lang, job.label));
  };
  tag.onerror = () => {
    aiHljs.state = "failed";
    aiHljs.queue = [];
  };
  document.head.appendChild(tag);
}

function aiHighlightNow(el, code, lang, label) {
  if (!el.isConnected && !el.closest(".ai-md")) return;
  try {
    const hl = window.hljs;
    const name = String(lang || "").toLowerCase();
    let result = null;
    if (name && hl.getLanguage(name)) result = hl.highlight(code, { language: name, ignoreIllegals: true });
    else if (!name && code.length < 20000) result = hl.highlightAuto(code);
    if (!result) return;
    el.innerHTML = result.value;
    el.classList.add("hljs");
    if (!name && result.language && result.relevance >= 5 && label) label.textContent = result.language;
  } catch {
  }
}

function aiHighlight(el, code, lang, label) {
  if (aiHljs.state === "ready") return aiHighlightNow(el, code, lang, label);
  if (aiHljs.state === "failed") return;
  aiHljs.queue.push({ el, code, lang, label });
  aiLoadHljs();
}

function aiCodeBlock(code, lang, live) {
  const wrap = aiEl("div", "ai-code");
  const head = aiEl("div", "ai-code-head");
  const label = aiEl("span", "", lang || "code");
  head.appendChild(label);
  const copy = aiEl("button", "ai-copy");
  copy.append(aiIcon("copy"), document.createTextNode(" Copy"));
  copy.onclick = () => aiCopy(code, copy);
  head.appendChild(copy);
  const pre = aiEl("pre");
  const codeEl = aiEl("code", "", code);
  pre.appendChild(codeEl);
  wrap.append(head, pre);
  if (!live) aiHighlight(codeEl, code, lang, label);
  return wrap;
}

function aiRender(text, live) {
  const box = aiEl("div", "ai-md");
  const lines = text.replace(/\r/g, "").split("\n");
  let i = 0;
  let list = null;
  let para = null;
  const endBlocks = () => {
    list = null;
    para = null;
  };
  while (i < lines.length) {
    const line = lines[i];
    const fence = line.match(/^\s*```\s*([\w+#.-]*)\s*$/);
    if (fence) {
      endBlocks();
      const code = [];
      i++;
      while (i < lines.length && !/^\s*```\s*$/.test(lines[i])) code.push(lines[i++]);
      i++;
      box.appendChild(aiCodeBlock(code.join("\n"), fence[1], live));
      continue;
    }
    const isRow = (l) => /^\s*\|.*\|\s*$/.test(l || "");
    const isDivider = (l) => /^\s*\|?\s*:?-{2,}:?\s*(\|\s*:?-{2,}:?\s*)+\|?\s*$/.test(l || "");
    if (isRow(line) && isDivider(lines[i + 1])) {
      endBlocks();
      const cells = (l) => l.trim().replace(/^\|/, "").replace(/\|$/, "").split("|").map((c) => c.trim());
      const wrap = aiEl("div", "ai-table-wrap");
      const table = aiEl("table", "ai-table");
      const thead = aiEl("thead");
      const hr = aiEl("tr");
      cells(line).forEach((c) => {
        const th = aiEl("th");
        aiInline(c, th);
        hr.appendChild(th);
      });
      thead.appendChild(hr);
      const tbody = aiEl("tbody");
      i += 2;
      while (i < lines.length && isRow(lines[i])) {
        const tr = aiEl("tr");
        cells(lines[i]).forEach((c) => {
          const td = aiEl("td");
          aiInline(c, td);
          tr.appendChild(td);
        });
        tbody.appendChild(tr);
        i++;
      }
      table.append(thead, tbody);
      wrap.appendChild(table);
      box.appendChild(wrap);
      continue;
    }
    const heading = line.match(/^(#{1,4})\s+(.*)$/);
    const bullet = line.match(/^\s*[-*•]\s+(.*)$/);
    const numbered = line.match(/^\s*(\d+)[.)]\s+(.*)$/);
    if (!line.trim()) {
      endBlocks();
    } else if (heading) {
      endBlocks();
      const h = aiEl("div", `ai-h ai-h${heading[1].length}`);
      aiInline(heading[2], h);
      box.appendChild(h);
    } else if (bullet || numbered) {
      const tag = bullet ? "ul" : "ol";
      if (!list || list.tagName.toLowerCase() !== tag) {
        para = null;
        list = aiEl(tag);
        if (numbered && numbered[1] !== "1") list.start = Number(numbered[1]);
        box.appendChild(list);
      }
      const li = aiEl("li");
      aiInline(bullet ? bullet[1] : numbered[2], li);
      list.appendChild(li);
    } else {
      list = null;
      if (!para) {
        para = aiEl("p");
        box.appendChild(para);
      } else {
        para.appendChild(document.createElement("br"));
      }
      aiInline(line, para);
    }
    i++;
  }
  return box;
}

function aiCopy(text, btn) {
  const done = () => {
    const old = btn.lastChild.textContent;
    btn.lastChild.textContent = " Copied";
    setTimeout(() => (btn.lastChild.textContent = old), 1500);
  };
  if (navigator.clipboard && navigator.clipboard.writeText) navigator.clipboard.writeText(text).then(done, () => {});
}

function aiTimeAgo(t) {
  const s = Math.max(0, (Date.now() - t) / 1000);
  if (s < 60) return "just now";
  if (s < 3600) return `${Math.floor(s / 60)}m ago`;
  if (s < 86400) return `${Math.floor(s / 3600)}h ago`;
  if (s < 86400 * 7) return `${Math.floor(s / 86400)}d ago`;
  return new Date(t).toLocaleDateString();
}

function aiRenderSide() {
  const ui = ai.ui;
  if (!ui) return;
  ui.chatList.replaceChildren();
  if (!ai.chats.length) {
    ui.chatList.appendChild(aiEl("div", "ai-side-empty", "Your chats will show up here."));
    return;
  }
  ai.chats.forEach((chat) => {
    const row = aiEl("div", `ai-chat-item${chat.id === ai.currentId ? " on" : ""}`);
    const text = aiEl("div", "ai-chat-text");
    text.appendChild(aiEl("div", "ai-chat-title", chat.title || aiTitleFrom(chat.messages)));
    text.appendChild(aiEl("div", "ai-chat-time", aiTimeAgo(chat.updated)));
    const rename = aiEl("button", "ai-chat-btn");
    rename.title = "Rename";
    rename.appendChild(aiIcon("pen"));
    const del = aiEl("button", "ai-chat-btn");
    del.title = "Delete";
    del.appendChild(aiIcon("trash"));
    row.append(text, rename, del);

    row.onclick = () => aiOpenChat(chat.id);
    rename.onclick = (e) => {
      e.stopPropagation();
      const input = document.createElement("input");
      input.className = "ai-chat-rename";
      input.maxLength = 60;
      input.value = chat.title || aiTitleFrom(chat.messages);
      text.replaceChildren(input);
      input.focus();
      input.select();
      let done = false;
      const finish = (save) => {
        if (done) return;
        done = true;
        const name = input.value.replace(/\s+/g, " ").trim().slice(0, 60);
        if (save && name) {
          chat.title = name;
          aiSaveChats();
        }
        aiRenderSide();
      };
      input.onclick = (ev) => ev.stopPropagation();
      input.onkeydown = (ev) => {
        if (ev.key === "Enter") finish(true);
        else if (ev.key === "Escape") finish(false);
      };
      input.onblur = () => finish(true);
    };
    del.onclick = (e) => {
      e.stopPropagation();
      if (del.classList.contains("confirm")) {
        if (ai.busy && chat.id === ai.currentId && ai.controller) ai.controller.abort();
        ai.chats = ai.chats.filter((c) => c.id !== chat.id);
        if (ai.currentId === chat.id) ai.currentId = null;
        aiSaveChats();
        aiRenderAll();
      } else {
        del.classList.add("confirm");
        del.title = "Click again to delete";
        del.replaceChildren(aiIcon("check"));
        setTimeout(() => {
          if (!del.isConnected) return;
          del.classList.remove("confirm");
          del.title = "Delete";
          del.replaceChildren(aiIcon("trash"));
        }, 2500);
      }
    };
    ui.chatList.appendChild(row);
  });
}

function aiOpenChat(id) {
  if (ai.busy && ai.controller) ai.controller.abort();
  ai.currentId = id;
  aiSaveChats();
  aiSetStatus("");
  if (aiIsPhone()) aiToggleSide(false);
  aiRenderAll();
  if (ai.ui) ai.ui.input.focus();
}

function aiNewChat() {
  if (ai.busy && ai.controller) ai.controller.abort();
  ai.currentId = null;
  aiSaveChats();
  aiSetStatus("");
  if (aiIsPhone()) aiToggleSide(false);
  aiRenderAll();
  if (ai.ui) ai.ui.input.focus();
}

const AI_SIDE_KEY = "aether-ai-sidebar";
function aiIsPhone() {
  return window.matchMedia("(max-width: 760px)").matches;
}
function aiToggleSide(open, fromUser) {
  ai.sideOpen = open === undefined ? !ai.sideOpen : open;
  if (fromUser && !aiIsPhone()) {
    try {
      localStorage.setItem(AI_SIDE_KEY, ai.sideOpen ? "open" : "closed");
    } catch {
    }
  }
  if (ai.ui) {
    ai.ui.root.classList.toggle("side-open", ai.sideOpen);
    ai.ui.sideBtn.title = ai.sideOpen ? "Hide chats" : "Show chats";
    ai.ui.sideBtn.setAttribute("aria-expanded", String(ai.sideOpen));
  }
}
function aiSideStartOpen() {
  if (aiIsPhone()) return false;
  try {
    return localStorage.getItem(AI_SIDE_KEY) !== "closed";
  } catch {
    return true;
  }
}

function aiOpenImage(src) {
  const ui = ai.ui;
  if (!ui) return;
  const wrap = aiEl("div", "ai-lightbox");
  const img = document.createElement("img");
  img.src = src;
  img.alt = "";
  wrap.appendChild(img);
  const shut = () => {
    wrap.remove();
    document.removeEventListener("keydown", onKey, true);
  };
  const onKey = (e) => {
    if (e.key === "Escape") shut();
  };
  wrap.onclick = shut;
  document.addEventListener("keydown", onKey, true);
  ui.root.appendChild(wrap);
}

function aiImagesNode(msg) {
  const pics = (msg.images && msg.images.length ? msg.images : msg.thumbs) || [];
  if (!pics.length) return null;
  const box = aiEl("div", "ai-images");
  pics.forEach((src) => {
    const img = document.createElement("img");
    img.src = src;
    img.alt = "Attached image";
    img.onclick = () => aiOpenImage(src);
    box.appendChild(img);
  });
  return box;
}

function aiMessageNode(msg) {
  const row = aiEl("div", `ai-msg ai-${msg.role}`);
  const pics = msg.role === "user" ? aiImagesNode(msg) : null;
  if (pics) row.appendChild(pics);
  const bubble = aiEl("div", "ai-bubble");
  if (msg.role === "user") bubble.textContent = msg.content;
  else bubble.appendChild(aiRender(msg.content || ""));
  if (msg.role !== "user" || msg.content) row.appendChild(bubble);
  if (msg.role === "assistant" && msg.content) {
    const tools = aiEl("div", "ai-tools");
    const copy = aiEl("button", "ai-copy");
    copy.append(aiIcon("copy"), document.createTextNode(" Copy"));
    copy.onclick = () => aiCopy(msg.content, copy);
    tools.appendChild(copy);
    row.appendChild(tools);
  }
  return row;
}

function aiScroll(force) {
  const ui = ai.ui;
  if (!ui) return;
  const near = ui.list.scrollHeight - ui.list.scrollTop - ui.list.clientHeight < 120;
  if (force || near) ui.list.scrollTop = ui.list.scrollHeight;
}

function aiRenderMessages() {
  const ui = ai.ui;
  if (!ui) return;
  const chat = aiCurrent();
  ui.list.replaceChildren();
  if (!chat || !chat.messages.length) {
    const hello = aiEl("div", "ai-empty");
    hello.appendChild(aiEl("div", "ai-empty-title", "Ask me anything"));
    hello.appendChild(aiEl("div", "ai-empty-sub", "Homework help, explanations, ideas, writing feedback and more."));
    const starters = aiEl("div", "ai-starters");
    AI_STARTERS.forEach((q) => {
      const b = aiEl("button", "ai-starter", q);
      b.onclick = () => aiSend(q);
      starters.appendChild(b);
    });
    hello.appendChild(starters);
    ui.list.appendChild(hello);
  } else {
    chat.messages.forEach((m) => ui.list.appendChild(aiMessageNode(m)));
  }
  aiScroll(true);
}

function aiRenderAll() {
  const ui = ai.ui;
  if (!ui) return;
  aiRenderSide();
  aiRenderMessages();
  aiRenderKeyBadge();
  aiSyncControls();
}

function aiSyncControls() {
  const ui = ai.ui;
  if (!ui) return;
  ui.send.replaceChildren(aiIcon(ai.busy ? "stop" : "arrow-up"));
  ui.send.title = ai.busy ? "Stop" : "Send";
  ui.send.classList.toggle("stop", ai.busy);
  ui.send.disabled = !ai.busy && !ui.input.value.trim() && !ai.pending.length;
  ui.attach.disabled = ai.pending.length >= AI_MAX_IMAGES;
}

function aiLoadImage(file) {
  return new Promise((resolve, reject) => {
    const url = URL.createObjectURL(file);
    const img = new Image();
    img.onload = () => {
      URL.revokeObjectURL(url);
      resolve(img);
    };
    img.onerror = () => {
      URL.revokeObjectURL(url);
      reject(new Error("That file isn't an image I can read."));
    };
    img.src = url;
  });
}

function aiShrink(img, max, quality) {
  const scale = Math.min(1, max / Math.max(img.naturalWidth, img.naturalHeight));
  const canvas = document.createElement("canvas");
  canvas.width = Math.max(1, Math.round(img.naturalWidth * scale));
  canvas.height = Math.max(1, Math.round(img.naturalHeight * scale));
  const ctx = canvas.getContext("2d");
  ctx.fillStyle = "#fff";
  ctx.fillRect(0, 0, canvas.width, canvas.height);
  ctx.drawImage(img, 0, 0, canvas.width, canvas.height);
  return canvas.toDataURL("image/jpeg", quality);
}

async function aiAddFiles(files) {
  const list = Array.from(files || []).filter((f) => f && /^image\//.test(f.type));
  if (!list.length) return;
  aiSetStatus("");
  for (const file of list) {
    if (file.size > 25 * 1024 * 1024) {
      aiSetStatus("That image is too big. Try one under 25 MB.");
      continue;
    }
    try {
      const img = await aiLoadImage(file);
      ai.pending.push({ full: aiShrink(img, 1280, 0.85), thumb: aiShrink(img, 240, 0.7) });
    } catch (err) {
      aiSetStatus(err.message);
    }
  }
  aiRenderPending();
}

function aiRenderPending() {
  const ui = ai.ui;
  if (!ui) return;
  ui.attachRow.replaceChildren();
  ui.attachRow.hidden = !ai.pending.length;
  ai.pending.forEach((p, i) => {
    const item = aiEl("div", "ai-attach-item");
    const img = document.createElement("img");
    img.src = p.thumb;
    img.alt = "";
    const x = aiEl("button", "ai-attach-x");
    x.type = "button";
    x.title = "Remove";
    x.appendChild(aiIcon("xmark"));
    x.onclick = () => {
      ai.pending.splice(i, 1);
      aiRenderPending();
    };
    item.append(img, x);
    ui.attachRow.appendChild(item);
  });
  aiSyncControls();
}

function aiPayload(messages) {
  let room = AI_MAX_IMAGES;
  const out = [];
  for (let i = messages.length - 1; i >= 0; i--) {
    const m = messages[i];
    const item = { role: m.role, content: m.content };
    if (m.images && m.images.length && room > 0) {
      item.images = m.images.slice(0, room);
      room -= item.images.length;
    } else if ((m.images && m.images.length) || (m.thumbs && m.thumbs.length)) {
      item.content = `${m.content}\n[The user shared an image here earlier.]`.trim();
    }
    out.unshift(item);
  }
  return out;
}

function aiSetStatus(text, withKeyButton) {
  const ui = ai.ui;
  if (!ui) return;
  ui.status.replaceChildren();
  if (!text) return;
  ui.status.appendChild(document.createTextNode(text));
  if (withKeyButton) {
    const b = aiEl("button", "ai-status-btn", "Add your own key");
    b.onclick = () => aiOpenSettings({ focusKey: true });
    ui.status.append(" ", b);
  }
}

function aiRenderKeyBadge() {
  const ui = ai.ui;
  if (!ui) return;
  const k = aiPersonalKey();
  const p = k && AI_PROVIDERS.find((x) => x.id === k.provider);
  ui.gear.classList.toggle("on", Boolean(k));
  ui.gear.title = k ? `AI settings (using your ${p ? p.name : "own"} key)` : "AI settings";
  ui.note.replaceChildren();
  if (k) {
    ui.note.textContent = `Using your ${p ? p.name : "own"} key · AI can make mistakes. Double-check important answers.`;
    return;
  }
  if (typeof ai.remaining === "number" && ai.limit && ai.remaining <= 10) {
    const left = aiEl("button", "ai-left low", ai.remaining ? `Only ${ai.remaining} question${ai.remaining === 1 ? "" : "s"} left today` : "No questions left today");
    left.type = "button";
    left.title = "Open AI settings";
    left.onclick = () => aiOpenSettings();
    ui.note.append(left, document.createTextNode(" · "));
  }
  ui.note.appendChild(document.createTextNode("AI can make mistakes. Double-check important answers."));
}

function aiReadRemaining(r) {
  const left = r.headers.get("X-AI-Remaining");
  const limit = r.headers.get("X-AI-Limit");
  if (left === null || limit === null) return;
  ai.remaining = Math.max(0, Number(left) || 0);
  ai.limit = Number(limit) || ai.limit;
  aiRenderKeyBadge();
}

async function aiSend(text) {
  const ui = ai.ui;
  const question = String(text || "").trim().slice(0, 4000);
  const attached = ai.pending.slice();
  if (!ui || ai.busy || (!question && !attached.length)) return;
  aiSetStatus("");
  ai.pending = [];
  aiRenderPending();

  let chat = aiCurrent();
  if (!chat) {
    chat = { id: aiNewId(), title: "", updated: Date.now(), messages: [] };
    ai.chats.unshift(chat);
    ai.currentId = chat.id;
    ui.list.replaceChildren();
  }
  const userMsg = { role: "user", content: question };
  if (attached.length) {
    userMsg.images = attached.map((p) => p.full);
    userMsg.thumbs = attached.map((p) => p.thumb);
  }
  chat.messages.push(userMsg);
  chat.updated = Date.now();
  if (!chat.title) chat.title = aiTitleFrom(chat.messages);
  ai.chats.sort((a, b) => b.updated - a.updated);
  aiSaveChats();
  aiRenderSide();

  ui.list.appendChild(aiMessageNode(userMsg));
  ui.input.value = "";
  aiAutoGrow();

  const reply = { role: "assistant", content: "" };
  const row = aiEl("div", "ai-msg ai-assistant");
  const bubble = aiEl("div", "ai-bubble");
  bubble.appendChild(aiEl("div", "ai-typing")).append(aiEl("span"), aiEl("span"), aiEl("span"));
  row.appendChild(bubble);
  ui.list.appendChild(row);
  aiScroll(true);

  ai.busy = true;
  ai.controller = new AbortController();
  const myChat = chat;
  aiSyncControls();

  let failedNoKey = false;
  try {
    const r = await fetch("/api/ai/chat", {
      method: "POST",
      headers: { "Content-Type": "application/json", "X-AI-Style": aiSettings().length, ...aiKeyHeaders(aiPersonalKey()) },
      body: JSON.stringify({ messages: aiPayload(myChat.messages.slice(-20)) }),
      signal: ai.controller.signal,
    });
    aiReadRemaining(r);
    if (!r.ok) {
      const data = await r.json().catch(() => ({}));
      failedNoKey = (r.status === 503 || r.status === 429) && !aiPersonalKey();
      throw new Error(data.error || "The AI couldn't answer right now.");
    }
    const reader = r.body.getReader();
    const decoder = new TextDecoder();
    let pending = false;
    for (;;) {
      const { done, value } = await reader.read();
      if (done) break;
      reply.content += decoder.decode(value, { stream: true });
      if (!pending && ai.currentId === myChat.id) {
        pending = true;
        requestAnimationFrame(() => {
          pending = false;
          if (row.isConnected) {
            bubble.replaceChildren(aiRender(reply.content, true));
            aiScroll();
          }
        });
      }
    }
    reply.content += decoder.decode();
  } catch (err) {
    if (err.name !== "AbortError") {
      if (!reply.content) {
        myChat.messages.pop();
        if (!myChat.messages.length) ai.chats = ai.chats.filter((c) => c !== myChat);
        row.remove();
        if (ai.currentId === myChat.id || !myChat.messages.length) {
          if (!myChat.messages.length) ai.currentId = null;
          ui.input.value = question;
          ai.pending = attached;
          aiRenderPending();
          aiAutoGrow();
        }
      }
      aiSetStatus(err.message || "Something went wrong.", failedNoKey);
    }
  } finally {
    ai.busy = false;
    ai.controller = null;
    if (reply.content.trim()) {
      myChat.messages.push(reply);
      myChat.updated = Date.now();
    }
    aiSaveChats();
    if (ai.currentId === myChat.id) {
      if (reply.content.trim() && row.isConnected) row.replaceWith(aiMessageNode(reply));
      else if (row.isConnected && !reply.content.trim()) row.remove();
    }
    if (!aiCurrent()) aiRenderMessages();
    aiRenderSide();
    aiSyncControls();
    aiScroll();
    if (ui.root.isConnected) ui.input.focus();
  }
}

function aiAutoGrow() {
  const input = ai.ui && ai.ui.input;
  if (!input) return;
  input.style.height = "auto";
  input.style.height = `${Math.min(input.scrollHeight, 180)}px`;
  aiSyncControls();
}

const AI_SETTINGS_KEY = "aether-ai-settings";
const AI_SETTING_CHOICES = {
  length: [["short", "Short"], ["normal", "Normal"], ["detailed", "Detailed"]],
  size: [["small", "Small"], ["normal", "Normal"], ["large", "Large"]],
};

function aiSettings() {
  let s = {};
  try {
    s = JSON.parse(localStorage.getItem(AI_SETTINGS_KEY) || "{}") || {};
  } catch {
    s = {};
  }
  const pick = (name, value) => (AI_SETTING_CHOICES[name].some(([v]) => v === value) ? value : "normal");
  return { length: pick("length", s.length), size: pick("size", s.size), enterSends: s.enterSends !== false };
}

function aiSaveSettings(change) {
  const next = { ...aiSettings(), ...change };
  try {
    localStorage.setItem(AI_SETTINGS_KEY, JSON.stringify(next));
  } catch {
  }
  aiApplySettings();
  return next;
}

function aiApplySettings() {
  const ui = ai.ui;
  if (!ui) return;
  const s = aiSettings();
  ui.root.dataset.size = s.size;
  ui.input.placeholder = s.enterSends ? "Ask Aether AI a question..." : "Ask Aether AI a question... (Ctrl+Enter to send)";
}

function aiRefreshUsage() {
  return fetch("/api/ai/status")
    .then((r) => r.json())
    .then((d) => {
      if (d && d.unlimited) {
        ai.unlimited = true;
        ai.remaining = null;
        ai.limit = 0;
        aiRenderKeyBadge();
      }
      return d;
    })
    .catch(() => null);
}

function aiOpenSettings(options = {}) {
  const ui = ai.ui;
  if (!ui || ui.root.querySelector(".ai-modal-wrap")) return;
  const wrap = aiEl("div", "ai-modal-wrap");
  const modal = aiEl("div", "ai-modal ai-settings");
  wrap.appendChild(modal);

  const head = aiEl("div", "ai-modal-head");
  const headTitle = aiEl("div", "ai-modal-title");
  headTitle.append(aiIcon("gear"), document.createTextNode(" AI settings"));
  head.appendChild(headTitle);
  const close = aiEl("button", "ai-chat-btn");
  close.title = "Close";
  close.appendChild(aiIcon("xmark"));
  head.appendChild(close);
  modal.appendChild(head);

  const section = (icon, title) => {
    const sec = aiEl("section", "ai-set-section");
    const h = aiEl("div", "ai-set-heading");
    h.append(aiIcon(icon), document.createTextNode(` ${title}`));
    sec.appendChild(h);
    modal.appendChild(sec);
    return sec;
  };

  const usage = section("chart-simple", "Questions");
  const usageBody = aiEl("div", "ai-usage");
  usage.appendChild(usageBody);
  let usageChecked = false;
  const paintUsage = () => {
    usageBody.replaceChildren();
    const k = aiPersonalKey();
    if (k) {
      const p = AI_PROVIDERS.find((x) => x.id === k.provider);
      usageBody.append(
        aiEl("div", "ai-usage-big", "Unlimited"),
        aiEl("div", "ai-usage-sub", `You're using your own ${p ? p.name : ""} key, so the site's daily limit doesn't apply.`)
      );
      return;
    }
    if (ai.unlimited) {
      usageBody.append(aiEl("div", "ai-usage-big", "Unlimited"), aiEl("div", "ai-usage-sub", "There's no daily limit. Ask as many questions as you want."));
      return;
    }
    if (typeof ai.remaining !== "number" || !ai.limit) {
      if (!usageChecked) usageBody.appendChild(aiEl("div", "ai-usage-sub", "Checking..."));
      else if (ai.siteReady === false) usageBody.appendChild(aiEl("div", "ai-usage-sub", "The site's AI isn't set up right now. Add your own key below to keep using it."));
      else usageBody.appendChild(aiEl("div", "ai-usage-sub", "Couldn't load your question count right now. It'll show up here after your next question."));
      return;
    }
    const nums = aiEl("div", "ai-usage-nums");
    nums.append(aiEl("span", `ai-usage-big${ai.remaining <= 10 ? " low" : ""}`, String(ai.remaining)), aiEl("span", "ai-usage-of", ` of ${ai.limit} left`));
    const bar = aiEl("div", "ai-usage-bar");
    const fill = aiEl("div", `ai-usage-fill${ai.remaining <= 10 ? " low" : ""}`);
    fill.style.width = `${Math.max(0, Math.min(100, (ai.remaining / ai.limit) * 100))}%`;
    bar.appendChild(fill);
    usageBody.append(nums, bar, aiEl("div", "ai-usage-sub", "Your questions refill every 24 hours. Add your own key below for unlimited questions."));
  };
  paintUsage();
  aiRefreshUsage().then(() => {
    usageChecked = true;
    paintUsage();
  });

  const prefs = section("sliders", "Preferences");
  const s = aiSettings();
  const choice = (label, name, help) => {
    const row = aiEl("div", "ai-set-row");
    const text = aiEl("div", "ai-set-text");
    text.append(aiEl("div", "ai-set-label", label), aiEl("div", "ai-set-help", help));
    const seg = aiEl("div", "ai-seg");
    AI_SETTING_CHOICES[name].forEach(([value, text2]) => {
      const b = aiEl("button", `ai-seg-btn${s[name] === value ? " on" : ""}`, text2);
      b.type = "button";
      b.onclick = () => {
        aiSaveSettings({ [name]: value });
        s[name] = value;
        seg.querySelectorAll(".ai-seg-btn").forEach((x) => x.classList.toggle("on", x === b));
      };
      seg.appendChild(b);
    });
    row.append(text, seg);
    prefs.appendChild(row);
  };
  choice("Answer length", "length", "How long the AI's answers should be.");
  choice("Text size", "size", "Size of the text in your chats.");

  const enterRow = aiEl("div", "ai-set-row");
  const enterText = aiEl("div", "ai-set-text");
  enterText.append(aiEl("div", "ai-set-label", "Enter sends"), aiEl("div", "ai-set-help", "Off: Enter makes a new line and Ctrl+Enter sends."));
  const toggle = aiEl("button", `ai-toggle${s.enterSends ? " on" : ""}`);
  toggle.type = "button";
  toggle.setAttribute("role", "switch");
  toggle.setAttribute("aria-checked", String(s.enterSends));
  toggle.appendChild(aiEl("span", "ai-toggle-dot"));
  toggle.onclick = () => {
    s.enterSends = !s.enterSends;
    aiSaveSettings({ enterSends: s.enterSends });
    toggle.classList.toggle("on", s.enterSends);
    toggle.setAttribute("aria-checked", String(s.enterSends));
  };
  enterRow.append(enterText, toggle);
  prefs.appendChild(enterRow);

  const keySec = section("key", "Your own API key");
  const saved = aiPersonalKey();
  keySec.appendChild(
    aiEl("p", "ai-modal-text", "Use your own AI key instead of the site's. Answers come from your account with that service, and you won't hit the site's daily limit.")
  );

  const provLabel = aiEl("label", "ai-field");
  provLabel.appendChild(aiEl("span", "", "Service"));
  const prov = document.createElement("select");
  AI_PROVIDERS.forEach((p) => {
    const o = document.createElement("option");
    o.value = p.id;
    o.textContent = p.name;
    prov.appendChild(o);
  });
  prov.value = saved ? saved.provider : "groq";
  provLabel.appendChild(prov);

  const keyLabel = aiEl("label", "ai-field");
  keyLabel.appendChild(aiEl("span", "", "API key"));
  const keyRow = aiEl("div", "ai-key-row");
  const key = document.createElement("input");
  key.type = "password";
  key.autocomplete = "off";
  key.spellcheck = false;
  key.maxLength = 300;
  key.value = saved ? saved.key : "";
  const show = aiEl("button", "ai-chat-btn");
  show.type = "button";
  show.title = "Show or hide";
  show.appendChild(aiIcon("eye"));
  show.onclick = () => {
    key.type = key.type === "password" ? "text" : "password";
    show.replaceChildren(aiIcon(key.type === "password" ? "eye" : "eye-slash"));
  };
  keyRow.append(key, show);
  keyLabel.appendChild(keyRow);
  const hint = aiEl("div", "ai-field-hint");

  const modelLabel = aiEl("label", "ai-field");
  modelLabel.appendChild(aiEl("span", "", "Model (optional)"));
  const model = document.createElement("input");
  model.type = "text";
  model.autocomplete = "off";
  model.spellcheck = false;
  model.maxLength = 100;
  model.placeholder = "Leave blank for the default";
  model.value = saved ? saved.model : "";
  modelLabel.appendChild(model);

  const updateHint = () => {
    const p = AI_PROVIDERS.find((x) => x.id === prov.value);
    hint.replaceChildren(document.createTextNode(`${p.hint}. Get one at `));
    const a = aiEl("a", "", p.url.replace(/^https:\/\//, ""));
    a.href = p.url;
    a.target = "_blank";
    a.rel = "noopener noreferrer";
    hint.appendChild(a);
    key.placeholder = p.hint;
  };
  prov.onchange = updateHint;
  updateHint();

  const privacy = aiEl("p", "ai-modal-note", "Your key is only saved here not with cloud");
  const msg = aiEl("div", "ai-modal-msg");
  const btns = aiEl("div", "ai-modal-btns");
  const remove = aiEl("button", "ai-btn danger", "Remove my key");
  remove.hidden = !saved;
  const save = aiEl("button", "ai-btn main", "Test & save");
  btns.append(remove, save);
  keySec.append(provLabel, keyLabel, hint, modelLabel, privacy, msg, btns);

  const chatsSec = section("comments", "Chats");
  const chatsRow = aiEl("div", "ai-set-row");
  const chatsText = aiEl("div", "ai-set-text");
  chatsText.append(
    aiEl("div", "ai-set-label", "Delete all chats"),
    aiEl("div", "ai-set-help", `Removes all ${ai.chats.length} saved chat${ai.chats.length === 1 ? "" : "s"} from this browser and your account.`)
  );
  const wipe = aiEl("button", "ai-btn danger-solid", "Delete all");
  wipe.type = "button";
  wipe.disabled = !ai.chats.length;
  wipe.onclick = () => {
    if (!wipe.classList.contains("confirm")) {
      wipe.classList.add("confirm");
      wipe.textContent = "Click again to confirm";
      setTimeout(() => {
        if (!wipe.isConnected) return;
        wipe.classList.remove("confirm");
        wipe.textContent = "Delete all";
      }, 3000);
      return;
    }
    if (ai.busy && ai.controller) ai.controller.abort();
    ai.chats = [];
    ai.currentId = null;
    aiSaveChats();
    aiRenderAll();
    wipe.classList.remove("confirm");
    wipe.textContent = "Deleted";
    wipe.disabled = true;
    chatsText.lastChild.textContent = "No saved chats.";
  };
  chatsRow.append(chatsText, wipe);
  chatsSec.appendChild(chatsRow);

  ui.root.appendChild(wrap);
  if (options.focusKey) {
    setTimeout(() => {
      keySec.scrollIntoView({ block: "start" });
      key.focus();
    }, 0);
  } else {
    setTimeout(() => close.focus(), 0);
  }

  const shut = () => {
    wrap.remove();
    document.removeEventListener("keydown", onKey, true);
  };
  const onKey = (e) => {
    if (e.key === "Escape") shut();
  };
  document.addEventListener("keydown", onKey, true);
  close.onclick = shut;
  wrap.onclick = (e) => {
    if (e.target === wrap) shut();
  };
  const setMsg = (text, good) => {
    msg.textContent = text;
    msg.className = `ai-modal-msg${good ? " good" : text ? " bad" : ""}`;
  };

  remove.onclick = () => {
    aiSetPersonalKey(null);
    aiRenderKeyBadge();
    aiSetStatus(ai.siteReady === false ? "The site's AI isn't set up." : "", ai.siteReady === false);
    key.value = "";
    model.value = "";
    remove.hidden = true;
    setMsg("Your key was removed. You're back on the site's AI.", true);
    paintUsage();
    aiRefreshUsage().then(paintUsage);
  };

  const submit = async () => {
    const value = { provider: prov.value, key: key.value.trim(), model: model.value.trim() };
    if (!value.key) {
      setMsg("Paste your key first.");
      key.focus();
      return;
    }
    save.disabled = true;
    setMsg("Checking your key...", true);
    try {
      const r = await fetch("/api/ai/test", { method: "POST", headers: aiKeyHeaders(value) });
      const data = await r.json().catch(() => ({}));
      if (!r.ok) throw new Error(data.error || "That key didn't work.");
      aiSetPersonalKey(value);
      aiRenderKeyBadge();
      aiSetStatus("");
      remove.hidden = false;
      setMsg("Key works and is saved.", true);
      paintUsage();
    } catch (err) {
      setMsg(err.message || "That key didn't work.");
    } finally {
      save.disabled = false;
    }
  };
  save.onclick = submit;
  [key, model].forEach((el) =>
    el.addEventListener("keydown", (e) => {
      if (e.key === "Enter") submit();
    })
  );
}

function buildAiPage() {
  const root = aiEl("div", "ai-page");

  const side = aiEl("div", "ai-side");
  const sideTop = aiEl("div", "ai-side-top");
  const newBtn = aiEl("button", "ai-new");
  newBtn.append(aiIcon("plus"), document.createTextNode(" New chat"));
  newBtn.onclick = aiNewChat;
  const sideClose = aiEl("button", "ai-icon-btn ai-side-close");
  sideClose.title = "Hide chats";
  sideClose.appendChild(aiIcon("angles-right"));
  sideClose.onclick = () => aiToggleSide(false, true);
  sideTop.append(newBtn, sideClose);
  const sideLabel = aiEl("div", "ai-side-label", "Chats");
  const chatList = aiEl("div", "ai-chat-list");
  const syncNote = aiEl("div", "ai-side-note");
  syncNote.append(aiIcon("cloud"), document.createTextNode(" Chats sync when you're logged in to your Aether account."));
  side.append(sideTop, sideLabel, chatList, syncNote);

  const main = aiEl("div", "ai-main");
  const top = aiEl("div", "ai-top");
  const sideBtn = aiEl("button", "ai-icon-btn ai-side-btn");
  sideBtn.title = "Show chats";
  sideBtn.appendChild(aiIcon("bars-staggered"));
  sideBtn.onclick = () => aiToggleSide(undefined, true);
  const titleWrap = aiEl("div", "ai-title-wrap");
  const title = aiEl("div", "ai-logo");
  title.append(aiIcon("robot"), document.createTextNode(" Aether AI"));
  const gear = aiEl("button", "ai-icon-btn ai-gear");
  gear.type = "button";
  gear.title = "AI settings";
  gear.appendChild(aiIcon("gear"));
  gear.onclick = () => aiOpenSettings();
  titleWrap.append(title, gear);
  top.append(titleWrap, sideBtn);

  const list = aiEl("div", "ai-list");
  const status = aiEl("div", "ai-status");
  const form = aiEl("form", "ai-compose");
  const attachRow = aiEl("div", "ai-attach-row");
  attachRow.hidden = true;
  const attach = aiEl("button", "ai-attach");
  attach.type = "button";
  attach.title = "Add images";
  attach.appendChild(aiIcon("plus"));
  const fileInput = document.createElement("input");
  fileInput.type = "file";
  fileInput.accept = "image/*";
  fileInput.multiple = true;
  fileInput.hidden = true;
  attach.onclick = () => fileInput.click();
  fileInput.onchange = () => {
    aiAddFiles(fileInput.files);
    fileInput.value = "";
  };
  const input = document.createElement("textarea");
  input.rows = 1;
  input.maxLength = 4000;
  input.placeholder = "Ask Aether AI a question...";
  const send = aiEl("button", "ai-send");
  send.type = "submit";
  form.append(attachRow, attach, input, send, fileInput);
  input.addEventListener("paste", (e) => {
    const files = Array.from((e.clipboardData && e.clipboardData.files) || []).filter((f) => /^image\//.test(f.type));
    if (files.length) {
      e.preventDefault();
      aiAddFiles(files);
    }
  });
  let dragDepth = 0;
  main.addEventListener("dragenter", (e) => {
    if (!e.dataTransfer || !Array.from(e.dataTransfer.types || []).includes("Files")) return;
    e.preventDefault();
    dragDepth++;
    main.classList.add("dragging");
  });
  main.addEventListener("dragover", (e) => {
    if (e.dataTransfer && Array.from(e.dataTransfer.types || []).includes("Files")) e.preventDefault();
  });
  main.addEventListener("dragleave", () => {
    dragDepth = Math.max(0, dragDepth - 1);
    if (!dragDepth) main.classList.remove("dragging");
  });
  main.addEventListener("drop", (e) => {
    if (!e.dataTransfer || !e.dataTransfer.files.length) return;
    e.preventDefault();
    dragDepth = 0;
    main.classList.remove("dragging");
    aiAddFiles(e.dataTransfer.files);
  });
  const bottom = aiEl("div", "ai-bottom");
  bottom.append(form);
  const note = aiEl("div", "ai-note", "AI can make mistakes. Double-check important answers.");
  main.append(top, list, status, bottom, note);

  const scrim = aiEl("div", "ai-scrim");
  scrim.onclick = () => aiToggleSide(false, true);

  root.append(main, scrim, side);
  ai.ui = { root, list, status, input, send, chatList, gear, sideBtn, note, attach, attachRow };
  aiApplySettings();
  aiToggleSide(aiSideStartOpen());

  form.onsubmit = (e) => {
    e.preventDefault();
    if (ai.busy) {
      if (ai.controller) ai.controller.abort();
      return;
    }
    aiSend(input.value);
  };
  input.addEventListener("input", aiAutoGrow);
  input.addEventListener("keydown", (e) => {
    const sendKey = aiSettings().enterSends ? !e.shiftKey && !e.ctrlKey && !e.metaKey : e.ctrlKey || e.metaKey;
    if (e.key === "Enter" && sendKey && !e.isComposing) {
      e.preventDefault();
      if (!ai.busy) aiSend(input.value);
    }
  });

  aiLoadChats();
  aiRenderAll();
  fetch("/api/ai/status")
    .then((r) => r.json())
    .then((d) => {
      ai.siteReady = Boolean(d && d.ready);
      if (d && d.unlimited) {
        ai.unlimited = true;
        ai.remaining = null;
        ai.limit = 0;
        aiRenderKeyBadge();
      }
      if (!ai.siteReady && !aiPersonalKey()) aiSetStatus("The site's AI isn't set up.", true);
    })
    .catch(() => {});
  setTimeout(() => input.focus(), 0);
  return root;
}

/**/

/**/
const CHAT_BADGES = {
  owner: ["crown", "Owner"],
  admin: ["shield-halved", "Admin"],
  developer: ["code", "Developer"],
  early: ["seedling", "Early user"],
  veteran: ["medal", "Veteran"],
  bughunter: ["bug", "Bug hunter"],
  musiclover: ["headphones", "Music lover"],
};

const chat = { es: null, me: null, muted: null, ui: null, ids: new Set(), sending: false, watch: null };

function chatEl(tag, cls, text) {
  const e = document.createElement(tag);
  if (cls) e.className = cls;
  if (text !== undefined) e.textContent = text;
  return e;
}

function chatIcon(name) {
  const i = document.createElement("i");
  i.className = `fa-solid fa-${name}`;
  return i;
}

async function chatPost(path, body) {
  const r = await fetch(`/api/chat/${path}`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(body || {}),
    credentials: "same-origin",
  });
  const data = await r.json().catch(() => ({}));
  if (!r.ok) throw new Error(data.error || "Something went wrong.");
  return data;
}

function chatTime(t) {
  const d = new Date(t);
  const today = new Date().toDateString() === d.toDateString();
  const time = d.toLocaleTimeString([], { hour: "numeric", minute: "2-digit" });
  return today ? time : `${d.toLocaleDateString([], { month: "short", day: "numeric" })} ${time}`;
}

const CHAT_TOKEN_RE = /https?:\/\/[^\s<>()]+[^\s<>().,!?;:'"]|(^|[^\w@])@([A-Za-z0-9_.-]{1,32})/g;

function chatMentions(text) {
  const out = new Set();
  for (const m of text.matchAll(CHAT_TOKEN_RE)) if (m[2]) out.add(m[2].replace(/[.-]+$/, "").toLowerCase());
  return out;
}

function chatLinkify(text, parent) {
  let last = 0;
  for (const m of text.matchAll(CHAT_TOKEN_RE)) {
    let start = m.index;
    let token = m[0];
    if (m[2] !== undefined) {
      start += m[1].length;
      token = `@${m[2].replace(/[.-]+$/, "")}`;
    }
    if (start > last) parent.appendChild(document.createTextNode(text.slice(last, start)));
    if (m[2] !== undefined) {
      const name = token.slice(1);
      const mine = chat.me && name.toLowerCase() === chat.me.username.toLowerCase();
      const span = chatEl("span", `chat-mention${mine ? " me" : ""}`, token);
      span.onclick = (e) => chatOpenProfile(name, e.currentTarget);
      parent.appendChild(span);
    } else {
      const a = chatEl("a", "", token);
      a.href = "#";
      a.onclick = (e) => {
        e.preventDefault();
        if (typeof createTab === "function") createTab(token);
      };
      parent.appendChild(a);
    }
    last = start + token.length;
  }
  if (last < text.length) parent.appendChild(document.createTextNode(text.slice(last)));
}

function chatClosePop() {
  document.querySelectorAll(".chat-pop, .chat-modal-wrap").forEach((e) => e.remove());
}

document.addEventListener("mousedown", (e) => {
  if (!e.target.closest(".chat-pop, .chat-name, .chat-mention, .chat-modal")) document.querySelectorAll(".chat-pop").forEach((p) => p.remove());
});
document.addEventListener("keydown", (e) => {
  if (e.key === "Escape") chatClosePop();
});

function chatBadgeRow(badges) {
  const row = chatEl("span", "chat-badges");
  (badges || []).forEach((b) => {
    const info = CHAT_BADGES[b];
    if (!info) return;
    const badge = chatEl("span", `chat-badge ${b}`);
    badge.title = info[1];
    badge.appendChild(chatIcon(info[0]));
    row.appendChild(badge);
  });
  return row;
}

async function chatOpenProfile(username, anchor) {
  chatClosePop();
  const root = chat.ui && chat.ui.root;
  if (!root) return;
  const pop = chatEl("div", "chat-pop");
  pop.appendChild(chatEl("div", "chat-pop-loading", "Loading..."));
  root.appendChild(pop);
  const a = anchor.getBoundingClientRect();
  const r = root.getBoundingClientRect();
  pop.style.left = `${Math.max(8, Math.min(a.left - r.left, r.width - 288))}px`;
  pop.style.top = `${a.bottom - r.top + 6}px`;
  try {
    const res = await fetch(`/api/chat/profile/${encodeURIComponent(username)}`, { credentials: "same-origin" });
    const d = await res.json();
    if (!res.ok) throw new Error(d.error || "Couldn't load that profile.");
    const p = d.profile;
    pop.replaceChildren();
    const head = chatEl("div", "chat-pop-head");
    const av = chatEl("div", "chat-avatar big", p.username.slice(0, 1).toUpperCase());
    av.style.setProperty("--hue", String([...p.username.toLowerCase()].reduce((h, c) => (h * 31 + c.charCodeAt(0)) % 360, 7)));
    const names = chatEl("div");
    names.appendChild(chatEl("div", `chat-name ${p.role || ""}`, p.username));
    names.appendChild(chatBadgeRow(p.badges));
    head.append(av, names);
    pop.appendChild(head);
    if (p.created) pop.appendChild(chatEl("div", "chat-pop-sub", `Joined ${new Date(p.created).toLocaleDateString([], { month: "long", day: "numeric", year: "numeric" })}`));
    const mine = chat.me && p.username.toLowerCase() === chat.me.username.toLowerCase();
    if (!mine) {
      const actions = chatEl("div", "chat-pop-actions");
      const mention = chatEl("button", "chat-pop-btn");
      mention.append(chatIcon("at"), document.createTextNode(" Mention"));
      mention.onclick = () => {
        chatClosePop();
        const input = chat.ui && chat.ui.input;
        if (!input || input.disabled) return;
        input.value = `${input.value.replace(/\s*$/, input.value.trim() ? " " : "")}@${p.username} `;
        chatGrow();
        input.focus();
      };
      const report = chatEl("button", "chat-pop-btn danger");
      report.append(chatIcon("flag"), document.createTextNode(" Report"));
      report.onclick = () => chatReport({ type: "user", username: p.username });
      actions.append(mention, report);
      pop.appendChild(actions);
    }
  } catch (err) {
    pop.replaceChildren(chatEl("div", "chat-pop-loading", err.message));
  }
}

function chatReport(target) {
  chatClosePop();
  const root = chat.ui && chat.ui.root;
  if (!root) return;
  const wrap = chatEl("div", "chat-modal-wrap");
  const modal = chatEl("div", "chat-modal");
  const title = target.type === "user" ? `Report ${target.username}` : `Report this message from ${target.username}`;
  modal.appendChild(chatEl("div", "chat-modal-title", title));
  if (target.text) modal.appendChild(chatEl("div", "chat-modal-quote", target.text));
  const reasons = ["Hate speech or slurs", "Bullying or harassment", "Spam", "Inappropriate content", "Other"];
  const pick = chatEl("div", "chat-modal-reasons");
  let chosen = "";
  reasons.forEach((r) => {
    const b = chatEl("button", "chat-reason", r);
    b.type = "button";
    b.onclick = () => {
      chosen = r;
      pick.querySelectorAll(".chat-reason").forEach((x) => x.classList.toggle("on", x === b));
      send.disabled = false;
    };
    pick.appendChild(b);
  });
  const details = document.createElement("textarea");
  details.className = "chat-modal-input";
  details.placeholder = "Anything else the moderators should know? (optional)";
  details.maxLength = 250;
  const status = chatEl("div", "chat-status");
  const row = chatEl("div", "chat-modal-actions");
  const cancel = chatEl("button", "chat-pop-btn", "Cancel");
  cancel.onclick = () => wrap.remove();
  const send = chatEl("button", "chat-pop-btn danger");
  send.append(chatIcon("flag"), document.createTextNode(" Send report"));
  send.disabled = true;
  send.onclick = async () => {
    send.disabled = true;
    try {
      const reason = details.value.trim() ? `${chosen}: ${details.value.trim()}` : chosen;
      const d = await chatPost("report", { type: target.type, id: target.id, username: target.username, reason });
      wrap.remove();
      chatStatus(d.already ? "You already reported that. The moderators will look at it." : "Thanks, your report was sent to the moderators.", "ok");
    } catch (err) {
      status.textContent = err.message;
      status.className = "chat-status error";
      send.disabled = false;
    }
  };
  row.append(cancel, send);
  modal.append(pick, details, status, row);
  wrap.appendChild(modal);
  wrap.addEventListener("mousedown", (e) => {
    if (e.target === wrap) wrap.remove();
  });
  root.appendChild(wrap);
}

function chatStatus(text, kind) {
  const ui = chat.ui;
  if (!ui) return;
  ui.status.textContent = text || "";
  ui.status.className = `chat-status ${kind || ""}`;
}

function chatCanModerate() {
  return Boolean(chat.me && chat.me.mod);
}

function chatMessageNode(m) {
  const row = chatEl("div", "chat-msg");
  row.dataset.id = m.id;
  const mine = chat.me && m.user.toLowerCase() === chat.me.username.toLowerCase();
  if (mine) row.classList.add("mine");
  const avatar = chatEl("div", "chat-avatar", m.user.slice(0, 1).toUpperCase());
  avatar.style.setProperty("--hue", String([...m.user.toLowerCase()].reduce((h, c) => (h * 31 + c.charCodeAt(0)) % 360, 7)));
  const body = chatEl("div", "chat-body");
  const head = chatEl("div", "chat-head");
  const name = chatEl("span", `chat-name ${m.role || ""}`, m.user);
  name.onclick = (e) => chatOpenProfile(m.user, e.currentTarget);
  avatar.onclick = (e) => chatOpenProfile(m.user, name);
  head.append(name, chatBadgeRow(m.badges));
  if (!mine && chat.me && chatMentions(m.text).has(chat.me.username.toLowerCase())) row.classList.add("mention-me");
  head.appendChild(chatEl("span", "chat-time", chatTime(m.at)));
  const text = chatEl("div", "chat-text");
  chatLinkify(m.text, text);
  body.append(head, text);

  const tools = chatEl("div", "chat-tools");
  if (mine || chatCanModerate()) {
    const del = chatEl("button", "chat-tool");
    del.title = "Delete message";
    del.appendChild(chatIcon("trash"));
    del.onclick = () => chatPost("delete", { id: m.id }).catch((err) => chatStatus(err.message, "error"));
    tools.appendChild(del);
  }
  if (!mine) {
    const rep = chatEl("button", "chat-tool");
    rep.title = "Report message";
    rep.appendChild(chatIcon("flag"));
    rep.onclick = () => chatReport({ type: "message", id: m.id, username: m.user, text: m.text });
    tools.appendChild(rep);
  }
  if (!mine && chatCanModerate() && m.role !== "owner") {
    const mute = chatEl("button", "chat-tool");
    mute.title = `Mute ${m.user} for 1 hour`;
    mute.appendChild(chatIcon("volume-xmark"));
    mute.onclick = () =>
      chatPost("mute", { username: m.user, minutes: 60, reason: "Muted from chat" })
        .then(() => chatStatus(`${m.user} is muted for 1 hour. Change it in the dashboard's Chat tab.`, "ok"))
        .catch((err) => chatStatus(err.message, "error"));
    tools.appendChild(mute);
  }
  row.append(avatar, body, tools);
  return row;
}

function chatNearBottom() {
  const list = chat.ui && chat.ui.list;
  return !list || list.scrollHeight - list.scrollTop - list.clientHeight < 120;
}

function chatScroll(force) {
  const list = chat.ui && chat.ui.list;
  if (list && (force || chatNearBottom())) list.scrollTop = list.scrollHeight;
}

function chatAdd(m, force) {
  const ui = chat.ui;
  if (!ui || chat.ids.has(m.id)) return;
  chat.ids.add(m.id);
  const stick = chatNearBottom();
  const empty = ui.list.querySelector(".chat-empty");
  if (empty) empty.remove();
  ui.list.appendChild(chatMessageNode(m));
  chatScroll(force || stick);
}

function chatEmpty() {
  const box = chatEl("div", "chat-empty");
  box.appendChild(chatEl("div", "chat-empty-icon")).appendChild(chatIcon("comments"));
  box.appendChild(chatEl("div", "chat-empty-title", "No messages yet"));
  box.appendChild(chatEl("div", "chat-empty-sub", "Say hi to get things going."));
  return box;
}

function chatSyncMuted() {
  const ui = chat.ui;
  if (!ui) return;
  const m = chat.muted;
  ui.input.disabled = Boolean(m);
  ui.send.disabled = Boolean(m) || !ui.input.value.trim() || chat.sending;
  if (m) {
    const until = m.until ? ` until ${new Date(m.until).toLocaleString()}` : "";
    ui.input.placeholder = `You're muted${until}.`;
    chatStatus(`You're muted${until}.${m.reason ? ` Reason: ${m.reason}` : ""}`, "error");
  } else {
    ui.input.placeholder = "Message the chat...";
  }
}

function chatClose() {
  if (chat.es) chat.es.close();
  chat.es = null;
  clearInterval(chat.watch);
  chat.watch = null;
}

function chatConnect() {
  chatClose();
  const es = new EventSource("/api/chat/stream", { withCredentials: true });
  chat.es = es;
  es.addEventListener("hello", (e) => {
    const d = JSON.parse(e.data);
    chat.me = d.me;
    chat.muted = d.muted;
    chat.ids.clear();
    const ui = chat.ui;
    if (!ui) return;
    ui.list.replaceChildren();
    if (!d.messages.length) ui.list.appendChild(chatEmpty());
    d.messages.forEach((m) => chatAdd(m, true));
    ui.online.textContent = `${d.online} online`;
    chatStatus("");
    chatMarkSeen();
    chatSyncMuted();
    chatScroll(true);
  });
  es.addEventListener("message", (e) => {
    const m = JSON.parse(e.data);
    chatAdd(m);
    if (chat.me && m.user.toLowerCase() !== chat.me.username.toLowerCase() && chatMentions(m.text).has(chat.me.username.toLowerCase())) chatMarkSeen();
  });
  es.addEventListener("delete", (e) => {
    const { id } = JSON.parse(e.data);
    const node = chat.ui && chat.ui.list.querySelector(`[data-id="${CSS.escape(id)}"]`);
    if (node) node.remove();
    chat.ids.delete(id);
    if (chat.ui && !chat.ui.list.children.length) chat.ui.list.appendChild(chatEmpty());
  });
  es.addEventListener("online", (e) => {
    if (chat.ui) chat.ui.online.textContent = `${JSON.parse(e.data).count} online`;
  });
  es.addEventListener("muted", (e) => {
    chat.muted = JSON.parse(e.data);
    chatSyncMuted();
  });
  es.addEventListener("unmuted", () => {
    chat.muted = null;
    chatStatus("You can chat again.", "ok");
    chatSyncMuted();
  });
  es.onerror = () => {
    if (es.readyState === EventSource.CLOSED) {
      chatStatus("Lost connection to the chat. Reconnecting...", "error");
      setTimeout(() => {
        if (chat.ui && chat.ui.root.isConnected && chat.es === es) chatConnect();
      }, 3000);
    } else {
      chatStatus("Reconnecting...", "");
    }
  };
  chat.watch = setInterval(() => {
    if (!chat.ui || !chat.ui.root.isConnected) chatClose();
  }, 3000);
}

async function chatSend() {
  const ui = chat.ui;
  const text = ui.input.value.trim();
  if (!text || chat.sending || chat.muted) return;
  chat.sending = true;
  chatSyncMuted();
  try {
    const d = await chatPost("send", { text });
    ui.input.value = "";
    chatGrow();
    chatStatus("");
    if (d.message) chatAdd(d.message, true);
  } catch (err) {
    chatStatus(err.message, "error");
  } finally {
    chat.sending = false;
    chatSyncMuted();
    ui.input.focus();
  }
}

function chatGrow() {
  const input = chat.ui && chat.ui.input;
  if (!input) return;
  input.style.height = "auto";
  input.style.height = `${Math.min(input.scrollHeight, 140)}px`;
  chat.ui.counter.textContent = input.value.length > 400 ? `${input.value.length}/500` : "";
  chatSyncMuted();
}

function chatLoggedOut(root) {
  const box = chatEl("div", "chat-gate");
  box.appendChild(chatEl("div", "chat-empty-icon")).appendChild(chatIcon("lock"));
  box.appendChild(chatEl("div", "chat-empty-title", "Log in to chat"));
  box.appendChild(chatEl("div", "chat-empty-sub", "The chatroom is only open to people with an Aether account."));
  const btn = chatEl("button", "chat-gate-btn");
  btn.append(chatIcon("user"), document.createTextNode(" Log in or sign up"));
  btn.onclick = () => document.getElementById("account-btn").click();
  box.appendChild(btn);
  root.appendChild(box);
}

function buildChatPage() {
  chatClose();
  const root = chatEl("div", "chat-page");
  const top = chatEl("div", "chat-top");
  const title = chatEl("div", "chat-title");
  title.append(chatIcon("comments"), document.createTextNode(" Aether Chat"));
  const online = chatEl("div", "chat-online", "");
  top.append(title, online);
  root.appendChild(top);

  const shell = chatEl("div", "chat-shell");
  root.appendChild(shell);
  shell.appendChild(chatEl("div", "chat-loading", "Loading chat..."));

  fetch("/api/account/me", { credentials: "same-origin" })
    .then((r) => r.json())
    .then((d) => {
      shell.replaceChildren();
      if (!d || !d.user) {
        chat.ui = null;
        return chatLoggedOut(shell);
      }
      const list = chatEl("div", "chat-list");
      const status = chatEl("div", "chat-status");
      const form = chatEl("form", "chat-compose");
      const input = document.createElement("textarea");
      input.rows = 1;
      input.maxLength = 500;
      input.placeholder = "Message the chat...";
      const counter = chatEl("span", "chat-counter");
      const send = chatEl("button", "chat-send");
      send.type = "submit";
      send.title = "Send";
      send.appendChild(chatIcon("paper-plane"));
      form.append(input, counter, send);
      const note = chatEl("div", "chat-note", "Be nice. Messages are saved and checked by moderators.");
      shell.append(list, status, form, note);
      chat.ui = { root, list, status, input, send, online, counter };
      form.onsubmit = (e) => {
        e.preventDefault();
        chatSend();
      };
      input.addEventListener("input", chatGrow);
      input.addEventListener("keydown", (e) => {
        if (e.key === "Enter" && !e.shiftKey && !e.isComposing) {
          e.preventDefault();
          chatSend();
        }
      });
      chatSyncMuted();
      chatConnect();
      setTimeout(() => input.focus(), 0);
    })
    .catch(() => {
      shell.replaceChildren(chatEl("div", "chat-loading", "Couldn't load the chat. Try again in a moment."));
    });
  return root;
}

let chatSeenTimer = null;

function chatMarkSeen() {
  clearTimeout(chatSeenTimer);
  chatSeenTimer = setTimeout(() => {
    fetch("/api/chat/seen", { method: "POST", credentials: "same-origin" }).catch(() => {});
    chatSetDot(0);
  }, 400);
}

function chatOnPage() {
  return Boolean(chat.ui && chat.ui.root.isConnected && chat.ui.root.offsetParent !== null);
}

function chatSetDot(count) {
  const show = count > 0 && !chatOnPage();
  const label = count > 9 ? "9+" : String(count);
  const item = document.getElementById("chat-item");
  if (item) {
    let dot = item.querySelector(".chat-dot");
    if (show && !dot) dot = item.appendChild(chatEl("span", "chat-dot"));
    if (dot) {
      if (show) dot.textContent = label;
      else dot.remove();
    }
    item.title = show ? `${count} new mention${count === 1 ? "" : "s"}` : "";
  }
  const menu = document.getElementById("menu-btn");
  if (menu) menu.classList.toggle("has-chat-dot", show);
  if (typeof tabs !== "undefined" && Array.isArray(tabs)) {
    tabs.forEach((t) => {
      if (!t.tabBtn) return;
      const on = show && t.url === "aether://chat";
      t.tabBtn.classList.toggle("has-chat-dot", on);
    });
  }
}

async function chatPollUnread() {
  try {
    const r = await fetch("/api/chat/unread", { credentials: "same-origin" });
    if (r.ok) {
      const d = await r.json();
      if (d.mentions && chatOnPage()) chatMarkSeen();
      else chatSetDot(d.mentions || 0);
    } else chatSetDot(0);
  } catch {}
}

setInterval(chatPollUnread, 20000);
if (document.readyState === "loading") window.addEventListener("DOMContentLoaded", () => setTimeout(chatPollUnread, 1500));
else setTimeout(chatPollUnread, 1500);

/**/

/**/
(() => {
  const FLAKES_PER_PIXEL = 1 / 14000;
  const MAX_FLAKES = 140;
  const layers = new Set();

  function snowWanted() {
    const winter = typeof getCurrentSeason === "function" && getCurrentSeason() === "winter";
    const on = typeof getUiPref === "function" ? getUiPref("snow") === "on" : true;
    const calm = typeof reduceMotionOn === "function" && reduceMotionOn();
    return winter && on && !calm;
  }

  function makeFlake(w, h, anywhere) {
    const r = Math.random() * 2.2 + 0.8;
    return {
      x: Math.random() * w,
      y: anywhere ? Math.random() * h : -10 - Math.random() * 40,
      r,
      speed: 0.25 + r * 0.22 + Math.random() * 0.3,
      drift: Math.random() * Math.PI * 2,
      sway: 0.3 + Math.random() * 0.6,
      alpha: 0.35 + Math.random() * 0.5,
    };
  }

  function attach(page) {
    if (page._snow) return;
    const canvas = document.createElement("canvas");
    canvas.className = "snow-canvas";
    canvas.setAttribute("aria-hidden", "true");
    page.prepend(canvas);
    const ctx = canvas.getContext("2d");
    const layer = { page, canvas, ctx, flakes: [], w: 0, h: 0, raf: 0 };
    page._snow = layer;
    layers.add(layer);

    const resize = () => {
      const dpr = Math.min(window.devicePixelRatio || 1, 2);
      layer.w = page.clientWidth;
      layer.h = page.clientHeight;
      canvas.width = Math.max(1, Math.round(layer.w * dpr));
      canvas.height = Math.max(1, Math.round(layer.h * dpr));
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      const want = Math.min(MAX_FLAKES, Math.round(layer.w * layer.h * FLAKES_PER_PIXEL));
      while (layer.flakes.length < want) layer.flakes.push(makeFlake(layer.w, layer.h, true));
      layer.flakes.length = want;
    };
    layer.resize = resize;
    if (window.ResizeObserver) new ResizeObserver(resize).observe(page);
    resize();
    tick();
  }

  function frame(layer, dt) {
    const { ctx, w, h, flakes } = layer;
    ctx.clearRect(0, 0, w, h);
    ctx.fillStyle = "#ffffff";
    for (const f of flakes) {
      f.drift += 0.012 * dt;
      f.y += f.speed * dt;
      f.x += Math.sin(f.drift) * f.sway * 0.5 * dt;
      if (f.y > h + 6) Object.assign(f, makeFlake(w, h, false));
      if (f.x < -6) f.x = w + 6;
      else if (f.x > w + 6) f.x = -6;
      ctx.globalAlpha = f.alpha;
      ctx.beginPath();
      ctx.arc(f.x, f.y, f.r, 0, Math.PI * 2);
      ctx.fill();
    }
    ctx.globalAlpha = 1;
  }

  let running = false;
  let last = 0;

  function tick() {
    if (running) return;
    running = true;
    last = performance.now();
    requestAnimationFrame(loop);
  }

  function loop(now) {
    const dt = Math.min(3, (now - last) / 16.67);
    last = now;
    let any = false;
    const wanted = snowWanted();
    for (const layer of layers) {
      if (!layer.page.isConnected) {
        layers.delete(layer);
        continue;
      }
      const show = wanted && layer.page.offsetParent !== null && document.visibilityState === "visible";
      const disp = wanted ? "block" : "none";
      if (layer.canvas.style.display !== disp) layer.canvas.style.display = disp;
      if (show) {
        if (!layer.w) layer.resize();
        frame(layer, dt);
        any = true;
      }
    }
    if (any) requestAnimationFrame(loop);
    else running = false;
  }

  function scan() {
    document.querySelectorAll(".newtab-page").forEach(attach);
    if (snowWanted()) tick();
    else
      layers.forEach((l) => {
        if (l.canvas.style.display !== "none") l.canvas.style.display = "none";
      });
  }

  const content = document.getElementById("tabcontent");
  if (content) new MutationObserver(scan).observe(content, { childList: true, subtree: true, attributes: true, attributeFilter: ["style"] });
  document.addEventListener("visibilitychange", scan);
  window.addEventListener("aether-uiprefs", scan);
  setInterval(scan, 60 * 1000);
  scan();
  window.aetherSnowRefresh = scan;
})();

