(function () {
  const KEY = "aether-bookmarks";
  const SHOW_KEY = "aether-bookmarks-visible";
  const bar = document.getElementById("bookmarkbar");
  const star = document.getElementById("bookmark-star");
  if (!bar || !star) return;

  const read = (k, d) => {
    try {
      const v = localStorage.getItem(k);
      return v === null ? d : v;
    } catch {
      return d;
    }
  };
  const write = (k, v) => {
    try {
      localStorage.setItem(k, v);
    } catch {
    }
  };

  let marks = [];
  try {
    marks = JSON.parse(read(KEY, "[]"));
    if (!Array.isArray(marks)) marks = [];
  } catch {
    marks = [];
  }
  let visible = read(SHOW_KEY, "1") !== "0";

  const save = () => write(KEY, JSON.stringify(marks));
  const isWeb = (u) => /^https?:\/\//i.test(u || "");
  const host = (u) => {
    try {
      return new URL(u).hostname.replace(/^www\./, "");
    } catch {
      return u;
    }
  };
  const currentUrl = () => {
    try {
      return tabs.find((t) => t.id === activeTabId)?.url || "";
    } catch {
      return "";
    }
  };

  function icon(m) {
    const img = document.createElement("img");
    img.className = "bm-icon";
    img.alt = "";
    img.src = `https://icons.duckduckgo.com/ip3/${host(m.url)}.ico`;
    img.onerror = () => {
      const i = document.createElement("i");
      i.className = "fa-solid fa-globe bm-icon";
      img.replaceWith(i);
    };
    return img;
  }

  let menu = null;
  function closeMenu() {
    if (menu) menu.remove();
    menu = null;
  }
  function openMenu(x, y, entries) {
    closeMenu();
    menu = document.createElement("div");
    menu.className = "bm-menu";
    entries.forEach((e) => {
      const row = document.createElement("div");
      row.className = "bm-menu-row";
      if (e.node) row.appendChild(e.node);
      else row.textContent = e.label;
      row.onclick = () => {
        closeMenu();
        e.run && e.run();
      };
      menu.appendChild(row);
    });
    document.body.appendChild(menu);
    const r = menu.getBoundingClientRect();
    menu.style.left = Math.max(4, Math.min(x, window.innerWidth - r.width - 4)) + "px";
    menu.style.top = Math.max(4, Math.min(y, window.innerHeight - r.height - 4)) + "px";
  }
  document.addEventListener("mousedown", (e) => {
    if (menu && !menu.contains(e.target)) closeMenu();
  });
  window.addEventListener("blur", closeMenu);

  function open(m, newTab) {
    if (newTab) createTab(m.url);
    else navigate(m.url);
  }
  function rename(m) {
    const t = prompt("Bookmark name:", m.title);
    if (t === null || !t.trim()) return;
    m.title = t.trim().slice(0, 80);
    save();
    render();
  }
  function remove(m) {
    marks = marks.filter((x) => x.id !== m.id);
    save();
    render();
  }
  function moveBefore(dragId, targetId) {
    const from = marks.findIndex((x) => x.id === dragId);
    if (from < 0 || dragId === targetId) return;
    const [m] = marks.splice(from, 1);
    const to = targetId ? marks.findIndex((x) => x.id === targetId) : marks.length;
    marks.splice(to < 0 ? marks.length : to, 0, m);
    save();
    render();
  }
  function itemMenu(e, m) {
    e.preventDefault();
    openMenu(e.clientX, e.clientY, [
      { label: "Open in new tab", run: () => open(m, true) },
      { label: "Rename…", run: () => rename(m) },
      { label: "Delete", run: () => remove(m) },
    ]);
  }

  let overflowBtn = null;
  function render() {
    bar.innerHTML = "";
    bar.hidden = !visible;
    document.body.classList.toggle("has-bookmarkbar", visible);

    if (!marks.length) {
      const hint = document.createElement("span");
      hint.className = "bm-hint";
      hint.textContent = "No bookmarks. Click the star on a page to add one";
      bar.appendChild(hint);
    }

    marks.forEach((m) => {
      const el = document.createElement("div");
      el.className = "bm-item";
      el.dataset.id = m.id;
      el.title = `${m.title}\n${m.url}`;
      el.draggable = true;
      const label = document.createElement("span");
      label.textContent = m.title;
      el.append(icon(m), label);
      el.addEventListener("click", (e) => open(m, e.ctrlKey || e.metaKey));
      el.addEventListener("auxclick", (e) => {
        if (e.button === 1) open(m, true);
      });
      el.addEventListener("contextmenu", (e) => itemMenu(e, m));
      el.addEventListener("dragstart", (e) => {
        e.dataTransfer.setData("text/plain", m.id);
        e.dataTransfer.effectAllowed = "move";
        el.classList.add("dragging");
      });
      el.addEventListener("dragend", () => {
        el.classList.remove("dragging");
        bar.querySelectorAll(".drop-before").forEach((x) => x.classList.remove("drop-before"));
      });
      el.addEventListener("dragover", (e) => {
        e.preventDefault();
        el.classList.add("drop-before");
      });
      el.addEventListener("dragleave", () => el.classList.remove("drop-before"));
      el.addEventListener("drop", (e) => {
        e.preventDefault();
        e.stopPropagation();
        moveBefore(e.dataTransfer.getData("text/plain"), m.id);
      });
      bar.appendChild(el);
    });

    overflowBtn = document.createElement("button");
    overflowBtn.className = "bm-more";
    overflowBtn.title = "More bookmarks";
    overflowBtn.innerHTML = '<i class="fa-solid fa-angles-right"></i>';
    overflowBtn.hidden = true;
    overflowBtn.onclick = () => {
      const r = overflowBtn.getBoundingClientRect();
      const hidden = marks.filter((m) => bar.querySelector(`.bm-item[data-id="${m.id}"]`)?.classList.contains("bm-overflow"));
      openMenu(
        r.right - 200,
        r.bottom + 4,
        hidden.map((m) => {
          const node = document.createElement("span");
          node.className = "bm-menu-item";
          node.append(icon(m), Object.assign(document.createElement("span"), { textContent: m.title }));
          return { node, run: () => open(m, false) };
        })
      );
    };
    bar.appendChild(overflowBtn);

    updateOverflow();
    updateStar();
  }

  function updateOverflow() {
    if (!visible || !overflowBtn) return;
    const items = [...bar.querySelectorAll(".bm-item")];
    items.forEach((i) => i.classList.remove("bm-overflow"));
    overflowBtn.hidden = true;
    const limit = bar.clientWidth - 16;
    let used = 0;
    let cut = false;
    items.forEach((i) => {
      const w = i.offsetWidth + 2;
      if (!cut && used + w > limit - 36) cut = true;
      if (cut) i.classList.add("bm-overflow");
      else used += w;
    });
    overflowBtn.hidden = !cut;
  }

  bar.addEventListener("dragover", (e) => e.preventDefault());
  bar.addEventListener("drop", (e) => {
    e.preventDefault();
    moveBefore(e.dataTransfer.getData("text/plain"), null);
  });
  bar.addEventListener("contextmenu", (e) => {
    if (e.target.closest(".bm-item")) return;
    e.preventDefault();
    openMenu(e.clientX, e.clientY, [{ label: "Hide bookmarks bar", run: () => setVisible(false) }]);
  });

  function updateStar() {
    const u = currentUrl();
    const on = isWeb(u) && marks.some((m) => m.url === u);
    star.classList.toggle("on", on);
    star.classList.toggle("disabled", !isWeb(u));
    star.title = !isWeb(u) ? "Only websites can be bookmarked" : on ? "Remove bookmark" : "Bookmark this page";
    star.innerHTML = `<i class="fa-${on ? "solid" : "regular"} fa-star"></i>`;
  }
  star.addEventListener("mousedown", (e) => e.preventDefault());
  star.addEventListener("click", () => {
    const u = currentUrl();
    if (!isWeb(u)) return;
    const have = marks.find((m) => m.url === u);
    if (have) marks = marks.filter((m) => m !== have);
    else marks.push({ id: Date.now().toString(36) + Math.random().toString(36).slice(2, 6), title: host(u), url: u });
    save();
    if (!visible) setVisible(true);
    else render();
  });

  function setVisible(v) {
    visible = v;
    write(SHOW_KEY, v ? "1" : "0");
    render();
    window.dispatchEvent(new Event("aether-bookmarkbar"));
  }

  document.addEventListener("keydown", (e) => {
    if ((e.ctrlKey || e.metaKey) && e.shiftKey && e.key.toLowerCase() === "b") {
      e.preventDefault();
      setVisible(!visible);
    }
  });
  window.addEventListener("aether-urlchange", updateStar);
  window.addEventListener("resize", updateOverflow);
  if (window.ResizeObserver) new ResizeObserver(updateOverflow).observe(bar);

  window.aetherBookmarks = { isVisible: () => visible, setVisible };
  render();
})();
