const state = { count: null, connected: false };

window.updateOnlineBadge = function (badge) {
  badge.classList.toggle("offline", !state.connected);
  badge.querySelector(".online-num").textContent =
    state.count === null ? "–" : state.count.toLocaleString();
};

window.renderOnlineBadges = function () {
  document.querySelectorAll(".online-badge").forEach((badge) => window.updateOnlineBadge(badge));
};

const app = initializeApp(firebaseConfig, "online-counter");
const auth = getAuth(app);
const db = getDatabase(app);

onValue(ref(db, "online"), (snap) => {
  state.count = snap.size;
  window.renderOnlineBadges();
});

onAuthStateChanged(auth, (user) => {
  if (!user) return;
  const tabRef = push(ref(db, `online/${user.uid}`));

  onValue(ref(db, ".info/connected"), (snap) => {
    state.connected = snap.val() === true;
    window.renderOnlineBadges();
    if (!state.connected) return;
    onDisconnect(tabRef).remove().then(() => set(tabRef, serverTimestamp()));
  });
});

signInAnonymously(auth).catch((err) => {
  console.error("[online-counter]", err);
  state.connected = false;
  window.renderOnlineBadges();
});

})().catch(function(e){console.error(e)});
